// Avtomatik yaratilgan (smartbsb-admin-src/build.mjs). Qo'lda o'zgartirmang.
export const APP = "/* smartbsb panel dasturi (admin.html va natijalar.html).\r\n   Bu fayl ochiq saytda turmaydi: build.mjs uni netlify/functions/lib/admin-app.mjs ga joylaydi,\r\n   server uni faqat admin paroli yoki faol obunasi bor o'qituvchiga beradi.\r\n   window.ADMIN = {root, mode: 'admin' | 'nj', api(part, body?), logout, name?, until?, onDownload?} */\r\n(function () {\r\n  const ADM = window.ADMIN;\r\n  const root = ADM.root;\r\n  const NJ = ADM.mode === 'nj';\r\n  const ls = {\r\n    get: (k, d) => { try { const v = localStorage.getItem(k); return v == null ? d : JSON.parse(v); } catch (e) { return d; } },\r\n    set: (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} },\r\n  };\r\n  const esc = (s) => String(s == null ? '' : s).replace(/[&<>\"]/g, (c) => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;'}[c]));\r\n  const h = (html) => { const t = document.createElement('template'); t.innerHTML = html.trim(); return t.content.firstElementChild; };\r\n\r\n  // Belgi (icons.js faqat admin.html da bor; natijalar.html da bo'sh qaytadi)\r\n  const ic = (k) => (window.li ? `<span class=\"lic\">${window.li(k)}</span>` : '');\r\n\r\n  const OY = ['yanvar', 'fevral', 'mart', 'aprel', 'may', 'iyun', 'iyul', 'avgust', 'sentabr', 'oktabr', 'noyabr', 'dekabr'];\r\n  const uzDate = (iso) => { if (!iso) return ''; const d = new Date(Date.parse(iso) + 5 * 3600e3); return `${d.getUTCDate()}-${OY[d.getUTCMonth()]} ${d.getUTCFullYear()}`; };\r\n\r\n  root.innerHTML = NJ\r\n    ? `<div class=\"app\">\r\n        <aside class=\"side\">\r\n          <a class=\"logo\" href=\"kabinet.html\"><img src=\"logo-96.png\" alt=\"\"><div><span><b>smart</b>bsb</span><small>NATIJALAR JADVALI</small></div></a>\r\n          <div class=\"nlabel\">BO'LIMLAR</div>\r\n          <nav class=\"nav\">\r\n            <button class=\"nv\" data-t=\"res\">${ic('table-2')}Natijalar jadvali</button>\r\n            <button class=\"nv\" data-t=\"hb\">${ic('chart-column')}BSB va CHSB hisoboti</button>\r\n          </nav>\r\n          <div class=\"sp\"></div>\r\n          <nav class=\"nav\">\r\n            <a class=\"nv\" href=\"kabinet.html\">${ic('layout-dashboard')}Kabinet</a>\r\n            <button class=\"nv\" id=\"thm\">${ic('contrast')}<span>Rejim</span></button>\r\n            <button class=\"nv\" id=\"lo\">${ic('log-out')}Chiqish</button>\r\n          </nav>\r\n        </aside>\r\n        <main class=\"main\">\r\n          <div class=\"hd\"><div><h1 id=\"ttl\"></h1><div class=\"mut\" id=\"ttl2\"></div></div>\r\n            <div class=\"pill\">${ic('circle-check')}Obuna ${esc(uzDate(ADM.until))} gacha faol</div></div>\r\n          <div id=\"tab\"></div>\r\n        </main>\r\n      </div>`\r\n    : `<div class=\"app\">\r\n        <aside class=\"side\">\r\n          <div class=\"logo\"><img src=\"logo-96.png\" alt=\"\"><div><span><b>smart</b>bsb</span><small>ADMIN PANEL</small></div></div>\r\n          <div class=\"nlabel\">BOSHQARUV</div>\r\n          <nav class=\"nav\">\r\n            <button class=\"nv\" data-t=\"tk\">${ic('zap')}Tokenlar</button>\r\n            <button class=\"nv\" data-t=\"sub\">${ic('key-round')}Obunachilar</button>\r\n            <button class=\"nv\" data-t=\"st\">${ic('chart-column')}Statistika</button>\r\n          </nav>\r\n          <div class=\"nlabel\">HUJJATLAR</div>\r\n          <nav class=\"nav\">\r\n            <button class=\"nv\" data-t=\"res\">${ic('table-2')}Natijalar jadvali</button>\r\n            <button class=\"nv\" data-t=\"sf\">${ic('percent')}Sifat tahlili</button>\r\n            <button class=\"nv\" data-t=\"hb\">${ic('chart-no-axes-column')}BSB va CHSB hisoboti</button>\r\n          </nav>\r\n          <div class=\"sp\"></div>\r\n          <nav class=\"nav\">\r\n            <button class=\"nv\" id=\"thm\">${ic('contrast')}<span>Rejim</span></button>\r\n            <button class=\"nv\" id=\"lo\">${ic('log-out')}Chiqish</button>\r\n          </nav>\r\n        </aside>\r\n        <main class=\"main\">\r\n          <div class=\"hd\"><div><h1 id=\"ttl\"></h1><div class=\"mut\" id=\"ttl2\"></div></div></div>\r\n          <div id=\"tab\"></div>\r\n        </main>\r\n      </div>`;\r\n  const tabs = NJ ? {res: Results, hb: Hisobot} : {res: Results, sf: Sifat, hb: Hisobot, sub: Subs, tk: Tokens, st: Stats};\r\n  const TTL = {\r\n    tk: ['Tokenlar', \"O'qituvchiga token berish, balanslar va kodlar\"],\r\n    sub: ['Obunachilar', 'Natijalar jadvali obunasi uchun kodlar'],\r\n    st: ['Statistika', 'Saytdan yuklab olingan fayllar'],\r\n    res: ['Natijalar jadvali', 'eMaktab jurnalidan tayyor rangli jadval'],\r\n    hb: ['BSB va CHSB hisoboti', 'Yillik natijalar: diagrammalar va umumiy jadval'],\r\n    sf: ['Sifat tahlili', \"Jurnal bo'yicha sifat ko'rsatkichlari hujjati\"],\r\n  };\r\n  const open = (t) => {\r\n    if (!tabs[t]) t = NJ ? 'res' : 'tk';\r\n    root.querySelectorAll('.nav [data-t]').forEach((b) => b.classList.toggle('on', b.dataset.t === t));\r\n    const box = root.querySelector('#tab');\r\n    box.innerHTML = '';\r\n    box.onclick = null;\r\n    root.querySelector('#ttl').textContent = TTL[t][0];\r\n    root.querySelector('#ttl2').textContent = NJ ? `Salom${ADM.name ? ', ' + ADM.name : ''}! ${TTL[t][1]}.` : TTL[t][1];\r\n    ls.set(NJ ? 'nj_tab' : 'adm_tab', t);\r\n    tabs[t](box);\r\n  };\r\n  root.querySelectorAll('.nav [data-t]').forEach((b) => (b.onclick = () => open(b.dataset.t)));\r\n  root.querySelector('#lo').onclick = ADM.logout;\r\n  {\r\n    // Yorug' / qorong'i rejim (kabinet bilan umumiy sozlama)\r\n    const thm = root.querySelector('#thm');\r\n    const lab = () => (thm.querySelector('span:last-child').textContent = document.documentElement.classList.contains('dark') ? \"Yorug' rejim\" : \"Qorong'i rejim\");\r\n    thm.onclick = () => {\r\n      const d = !document.documentElement.classList.contains('dark');\r\n      document.documentElement.classList.toggle('dark', d);\r\n      try { localStorage.setItem('smartbsb_theme', d ? 'dark' : 'light'); } catch (e) {}\r\n      lab();\r\n    };\r\n    lab();\r\n  }\r\n\r\n  /* ================= Natijalar jadvali ================= */\r\n\r\n  const GRADE = (t) => (t == null ? '' : t < 31 ? 2 : t < 66 ? 3 : t < 86 ? 4 : 5);\r\n  const FILL = {5: '92D050', 4: 'B7DEE8', 3: 'FFFF00', 2: 'F4B084'};\r\n  const PERIODS = ['I-chorak', 'II-chorak', 'III-chorak', 'IV-chorak', 'I-yarim yillik', 'II-yarim yillik', 'Yillik'];\r\n  const KINDS = {bsb: 'BSB', loyiha: 'Loyiha/Lab.', chsb: 'ChSB'};\r\n  const num = (v) => (typeof v === 'number' ? v : typeof v === 'string' && /^\\s*\\d+([.,]\\d+)?\\s*$/.test(v) ? parseFloat(v.replace(',', '.')) : null);\r\n  const roman = (n) => ['', 'I', 'II', 'III', 'IV'][n] || String(n);\r\n\r\n  // \"ABBOS QURBONNAZAR O‘G‘LI TURSUNOV\" -> \"Tursunov Abbos Qurbonnazar o‘g‘li\"\r\n  function teacherName(raw) {\r\n    const w = String(raw || '').trim().split(/\\s+/).filter(Boolean);\r\n    if (w.length < 2) return raw || '';\r\n    const cap = (s) => (/^(o[‘'`ʻ]?g[‘'`ʻ]?li|qizi)$/i.test(s) ? s.toLowerCase() : s.charAt(0).toUpperCase() + s.slice(1).toLowerCase());\r\n    return [w[w.length - 1], ...w.slice(0, -1)].map(cap).join(' ');\r\n  }\r\n  // \"Tursunov Abbos Qurbonnazar o‘g‘li\" -> \"A. Tursunov\"\r\n  const shortName = (full) => { const w = full.split(/\\s+/); return w.length > 1 ? `${w[1][0]}. ${w[0]}` : full; };\r\n\r\n  // eMaktab \"Fan jurnali\" eksportini o'qish\r\n  function parseJournal(aoa, file) {\r\n    const J = {file, cls: '', year: '', sub: '', teacher: '', period: '', cols: [], rows: [], warn: []};\r\n    for (const r of aoa.slice(0, 8)) {\r\n      const c = String(r[0] || '');\r\n      let m;\r\n      if ((m = c.match(/Sinf:\\s*(\\S+)\\s+(\\d{4})\\s*\\/\\s*(\\d{4})/))) { J.cls = m[1]; J.year = `${m[2]}-${m[3]}`; }\r\n      if ((m = c.match(/^Fan:\\s*(.+)/))) J.sub = m[1].trim();\r\n      if ((m = c.match(/FIO:\\s*(.+)/))) J.teacher = teacherName(m[1]);\r\n    }\r\n    const hr = aoa.findIndex((r) => r.some((c) => String(c).trim() === 'FB'));\r\n    if (hr < 0) throw new Error(\"Bu eMaktab jurnal fayliga o'xshamaydi (FB ustuni topilmadi)\");\r\n    const H = aoa[hr].map((c) => String(c).trim());\r\n    const T = (aoa[hr + 1] || []).map((c) => String(c).trim());\r\n    const MX = aoa[hr + 2] || [];\r\n    const fbC = H.indexOf('FB');\r\n    const balC = H.findIndex((c) => /^Ballar/i.test(c));\r\n    const tavC = H.findIndex((c) => /Tavsiya/i.test(c));\r\n    const finC = H.findIndex((c, j) => j > fbC && /chorak|yarim|yillik/i.test(c));\r\n    if (finC >= 0) {\r\n      const f = H[finC];\r\n      const n = parseInt(f, 10) || 1;\r\n      J.period = /yarim/i.test(f) ? `${roman(n)}-yarim yillik` : /yillik/i.test(f) ? 'Yillik' : `${roman(n)}-chorak`;\r\n    }\r\n    const ac = [];\r\n    T.forEach((t, j) => {\r\n      if (j >= fbC) return;\r\n      const kind = /^(CHSB|ChSB|ЧСБ)/i.test(t) ? 'chsb' : /^(BSB|БСБ)/i.test(t) ? 'bsb' : /loyiha|lab/i.test(t) ? 'loyiha' : null;\r\n      if (kind && num(MX[j]) != null) ac.push({j, kind, max: num(MX[j]), date: H[j]});\r\n    });\r\n    if (!ac.length) J.warn.push('Jurnalda BSB/ChSB ustunlari topilmadi');\r\n    // Taxmin: bir nechta BSB bo'lsa va oxirgisining maksimal bali boshqacha bo'lsa — bu Loyiha/Laboratoriya\r\n    const bs = ac.filter((c) => c.kind === 'bsb');\r\n    if (bs.length >= 2 && bs[bs.length - 1].max !== bs[0].max) bs[bs.length - 1].kind = 'loyiha';\r\n    J.cols = ac;\r\n    for (let i = hr + 3; i < aoa.length; i++) {\r\n      const r = aoa[i];\r\n      if (num(r[0]) == null || !String(r[1] || '').trim()) continue;\r\n      J.rows.push({\r\n        name: String(r[1]).replace(/\\s+/g, ' ').trim(),\r\n        v: ac.map((c) => num(r[c.j])),\r\n        fb: num(r[fbC]),\r\n        ballar: balC >= 0 ? num(r[balC]) : null,\r\n      });\r\n    }\r\n    if (!J.rows.length) J.warn.push(\"O'quvchilar topilmadi\");\r\n    if (!J.period) J.period = 'I-chorak';\r\n    return J;\r\n  }\r\n\r\n  // Jadval ustunlari tartibi: BSB..., Loyiha..., FB, ChSB...\r\n  function layout(J) {\r\n    const idx = (k) => J.cols.map((c, i) => [c, i]).filter(([c]) => c.kind === k);\r\n    const out = [];\r\n    idx('bsb').forEach(([c, i], n) => out.push({i, max: c.max, title: `${n + 1}-BSB (maksimal ${c.max} ball)`, short: `${n + 1}-BSB`}));\r\n    idx('loyiha').forEach(([c, i]) => out.push({i, max: c.max, title: `Loyiha ishi/\\nLaboratoriya (maksimal ${c.max} ball)`, short: 'Loyiha'}));\r\n    out.push({i: 'fb', max: 10, title: 'FB (maksimal 10 ball)', short: 'FB'});\r\n    idx('chsb').forEach(([c, i]) => out.push({i, max: c.max, title: `ChSB (maksimal ${c.max} ball)`, short: 'ChSB'}));\r\n    return out;\r\n  }\r\n  const cell = (r, c) => (c.i === 'fb' ? r.fb : r.v[c.i]);\r\n  function compute(J) {\r\n    const L = layout(J);\r\n    const maxSum = L.reduce((a, c) => a + (c.max || 0), 0);\r\n    // Baho faqat chorak to'liq bo'lsa (maksimal ballar yig'indisi 100) qo'yiladi — eMaktab ham shunday qiladi.\r\n    const full = Math.abs(maxSum - 100) < 0.01;\r\n    const rows = J.rows.map((r) => {\r\n      const vals = L.map((c) => cell(r, c));\r\n      const any = vals.some((v) => v != null && v !== 0) || r.v.some((v) => v != null);\r\n      const tot = any ? vals.reduce((a, v) => a + (v || 0), 0) : null;\r\n      return {name: r.name, vals, tot, g: full ? GRADE(tot) : '', ballar: r.ballar};\r\n    });\r\n    const cnt = {5: 0, 4: 0, 3: 0, 2: 0};\r\n    rows.forEach((r) => r.g && cnt[r.g]++);\r\n    const mism = rows.filter((r) => r.tot != null && r.ballar != null && Math.abs(r.tot - r.ballar) > 0.01).length;\r\n    return {L, rows, cnt, mism, maxSum, full};\r\n  }\r\n\r\n  const cfg = ls.get('adm_res_cfg', {school: '', ibdo: '', metod: ''});\r\n  let JOBS = [];\r\n\r\n  // Jurnal fayllarini o'qib JOBS ga qo'shadi (Natijalar jadvali va Sifat tahlili uchun umumiy). Xatolar matnini qaytaradi.\r\n  async function readJournals(fl) {\r\n    let err = '';\r\n    for (const f of fl) {\r\n      try {\r\n        const wb = XLSX.read(await f.arrayBuffer(), {type: 'array'});\r\n        const aoa = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], {header: 1, defval: '', raw: true});\r\n        const J = parseJournal(aoa, f.name);\r\n        J.sign = shortName(J.teacher);\r\n        JOBS.push(J);\r\n      } catch (e) {\r\n        err += `${f.name}: ${e.message}. `;\r\n      }\r\n    }\r\n    return err;\r\n  }\r\n\r\n  function Results(box) {\r\n    box.appendChild(h(`\r\n      <div class=\"card\">\r\n        <h2>Jurnal faylini yuklash</h2>\r\n        <p class=\"mut\" style=\"margin:-6px 0 14px\">eMaktab'dan yuklangan «Fan jurnali» Excel faylini tashlang — tayyor rangli natijalar jadvali chiqadi. Bir nechta sinf fayli bo'lsa, har biri alohida varaqqa tushadi.</p>\r\n        <div class=\"g3\">\r\n          <label>Maktab nomi<input id=\"cSchool\" placeholder=\"Qashqadaryo viloyati Nishon tumani 27-maktab\"></label>\r\n          <label>O‘.I.B.D.O‘<input id=\"cIbdo\" placeholder=\"A. E. Jo'rayev\"></label>\r\n          <label>Metod birlashma<input id=\"cMetod\" placeholder=\"S. A. G'oipov\"></label>\r\n        </div>\r\n        <label class=\"drop\" id=\"drop\"><input type=\"file\" id=\"fi\" accept=\".xls,.xlsx\" multiple hidden>\r\n          <b>Jurnal fayllarini shu yerga tashlang</b><span class=\"mut\">yoki bosib tanlang (.xls, bir nechta bo'lishi mumkin)</span></label>\r\n        <div id=\"err\" class=\"err\"></div>\r\n      </div>\r\n      `));\r\n    box.appendChild(h('<div id=\"jobs\"></div>'));\r\n    box.appendChild(h(`<div class=\"card bar2 hide\" id=\"dl\"><div><b id=\"dlT\"></b><div class=\"mut\">Formulalar saqlanadi: ballni o'zgartirsangiz, jami va baho o'zi qayta hisoblanadi.</div></div><button id=\"dlB\">Excel yuklab olish</button></div>`));\r\n    const $ = (s) => box.querySelector(s);\r\n    [['cSchool', 'school'], ['cIbdo', 'ibdo'], ['cMetod', 'metod']].forEach(([id, k]) => {\r\n      const el = $('#' + id);\r\n      el.value = cfg[k] || '';\r\n      el.oninput = () => { cfg[k] = el.value; ls.set('adm_res_cfg', cfg); };\r\n    });\r\n    const drop = $('#drop');\r\n    drop.ondragover = (e) => { e.preventDefault(); drop.classList.add('ov'); };\r\n    drop.ondragleave = () => drop.classList.remove('ov');\r\n    drop.ondrop = (e) => { e.preventDefault(); drop.classList.remove('ov'); addFiles([...e.dataTransfer.files]); };\r\n    $('#fi').onchange = (e) => { addFiles([...e.target.files]); e.target.value = ''; };\r\n    $('#dlB').onclick = () => download().catch((e) => { $('#err').textContent = 'Excel yaratib bo‘lmadi: ' + e.message; });\r\n\r\n    async function addFiles(fl) {\r\n      $('#err').textContent = await readJournals(fl);\r\n      draw();\r\n    }\r\n\r\n    function draw() {\r\n      const jb = $('#jobs');\r\n      jb.innerHTML = '';\r\n      JOBS.forEach((J, k) => jb.appendChild(jobCard(J, k)));\r\n      $('#dl').classList.toggle('hide', !JOBS.length);\r\n      $('#dlT').textContent = `${JOBS.length} ta sinf → ${JOBS.length} ta varaq`;\r\n    }\r\n\r\n    function jobCard(J, k) {\r\n      const R = compute(J);\r\n      const el = h(`\r\n        <div class=\"card job\">\r\n          <div class=\"jh\"><div><b>${esc(J.cls)} · ${esc(J.sub)}</b> <span class=\"mut\">${R.rows.length} o'quvchi · ${esc(J.file)}</span></div><button class=\"g sm\" data-x>Olib tashlash</button></div>\r\n          <div class=\"g4\">\r\n            <label>Sinf<input data-f=\"cls\"></label><label>Fan<input data-f=\"sub\"></label>\r\n            <label>Davr<select data-f=\"period\">${PERIODS.map((p) => `<option>${p}</option>`).join('')}</select></label>\r\n            <label>O‘quv yili<input data-f=\"year\"></label>\r\n            <label class=\"w2\">Fan o‘qituvchisi (sarlavhada)<input data-f=\"teacher\"></label>\r\n            <label>O‘qituvchi (imzoda)<input data-f=\"sign\"></label>\r\n          </div>\r\n          <div class=\"cols\">${J.cols.map((c, i) => `<span class=\"ct\"><span class=\"mut\">${esc(c.date)} · max ${c.max}</span><select data-c=\"${i}\">${Object.entries(KINDS).map(([v, n]) => `<option value=\"${v}\"${v === c.kind ? ' selected' : ''}>${n}</option>`).join('')}</select></span>`).join('')}</div>\r\n          ${J.warn.concat(R.mism ? [`${R.mism} ta o'quvchida jami ball eMaktab'dagi «Ballar» bilan mos emas — ustun turlarini tekshiring`] : [],\r\n            R.full ? [] : [`Chorak hali to'liq emas: maksimal ballar yig'indisi ${R.maxSum} (100 emas). Jami ball ko'rsatildi, baho esa qo'yilmadi — eMaktab ham bunday holatda baho qo'ymaydi. Barcha nazoratlar o'tkazilgach, baho o'zi chiqadi.`]).map((w) => `<div class=\"err\">⚠ ${esc(w)}</div>`).join('')}\r\n          <div class=\"tw\"><table class=\"pv\"><thead><tr><th>t/r</th><th>F.I.Sh.</th>${R.L.map((c) => `<th>${esc(c.short)}<br><span class=\"mut\">${c.max}</span></th>`).join('')}<th>Jami</th><th>Baho</th></tr></thead>\r\n          <tbody>${R.rows.map((r, i) => `<tr class=\"gr${r.g}\"><td>${i + 1}</td><td class=\"nm\">${esc(r.name)}</td>${r.vals.map((v) => `<td>${v == null ? '' : v}</td>`).join('')}<td><b>${r.tot == null ? '' : r.tot}</b></td><td><b>${r.g}</b></td></tr>`).join('')}</tbody></table></div>\r\n          <div class=\"mut\" style=\"margin-top:8px\">Jami baholar: «5» — ${R.cnt[5]} ta · «4» — ${R.cnt[4]} ta · «3» — ${R.cnt[3]} ta · «2» — ${R.cnt[2]} ta</div>\r\n        </div>`);\r\n      el.querySelectorAll('[data-f]').forEach((i) => {\r\n        i.value = J[i.dataset.f] || '';\r\n        i.onchange = () => { J[i.dataset.f] = i.value; if (i.dataset.f === 'cls' || i.dataset.f === 'sub') draw(); };\r\n      });\r\n      el.querySelectorAll('[data-c]').forEach((s) => (s.onchange = () => { J.cols[+s.dataset.c].kind = s.value; draw(); }));\r\n      el.querySelector('[data-x]').onclick = () => { JOBS.splice(k, 1); draw(); };\r\n      return el;\r\n    }\r\n  }\r\n\r\n  // ---------- Excel (ExcelJS) ----------\r\n  const colL = (n) => { let s = ''; for (n++; n > 0; n = Math.floor((n - 1) / 26)) s = String.fromCharCode(65 + ((n - 1) % 26)) + s; return s; };\r\n  const FONT = 'Times New Roman';\r\n  const thin = {style: 'thin', color: {argb: 'FF000000'}};\r\n  const BOX = {top: thin, left: thin, bottom: thin, right: thin};\r\n\r\n  function sheetFor(wb, J, used) {\r\n    const R = compute(J);\r\n    let nm = `${J.cls || 'Sinf'} ${J.sub || ''}`.trim().replace(/[\\\\/*?:[\\]]/g, '-').slice(0, 26) || 'Sinf';\r\n    for (let n = 2, b = nm; used.has(nm.toLowerCase()); n++) nm = `${b} (${n})`;\r\n    used.add(nm.toLowerCase());\r\n    const ws = wb.addWorksheet(nm, {pageSetup: {paperSize: 9, orientation: 'portrait', fitToPage: true, fitToWidth: 1, fitToHeight: 0, margins: {left: 0.4, right: 0.3, top: 0.4, bottom: 0.4, header: 0.2, footer: 0.2}}});\r\n    const nV = R.L.length;\r\n    const cTot = 3 + nV; // A=t/r, B=ism, C.. qiymatlar, keyin Jami\r\n    const cG = cTot + 1;\r\n    const last = colL(cG - 1);\r\n    const widths = [4.5, 34, ...R.L.map((c) => (c.short === 'Loyiha' ? 13.5 : 11.5)), 9, 10];\r\n    ws.columns = widths.map((width) => ({width}));\r\n    const f = (o) => ({name: FONT, size: 12, ...o});\r\n\r\n    ws.mergeCells(`A1:${last}1`);\r\n    Object.assign(ws.getCell('A1'), {value: cfg.school || '', font: f({bold: true, size: 13}), alignment: {horizontal: 'center', vertical: 'middle'}});\r\n    ws.mergeCells(`A2:${last}2`);\r\n    Object.assign(ws.getCell('A2'), {\r\n      value: `${J.cls} sinf oʻquvchilarining “${J.sub}” fanidan ${J.year}-oʻquv yili ${J.period} natijalari\\nFan oʻqituvchisi: ${J.teacher}`,\r\n      font: f({bold: true}),\r\n      alignment: {horizontal: 'center', vertical: 'middle', wrapText: true},\r\n    });\r\n    ws.getRow(1).height = 20;\r\n    // tor jadvalda sarlavha 2 qatordan ko'proqqa o'tadi — balandlikni shunga moslash\r\n    const tw = widths.reduce((s, w) => s + w, 0);\r\n    const lines = String(ws.getCell('A2').value).split(/\\n/).reduce((s, l) => s + Math.max(1, Math.ceil((l.length * 1.08) / tw)), 0);\r\n    ws.getRow(2).height = Math.max(36, lines * 17);\r\n    ws.getRow(3).height = 6;\r\n    if (!R.full) {\r\n      ws.mergeCells(`A3:${last}3`);\r\n      Object.assign(ws.getCell('A3'), {value: `Chorak hali to'liq emas (maksimal ${R.maxSum} ball) — baho barcha nazoratlar o'tkazilgach qo'yiladi`, font: f({italic: true, size: 10, color: {argb: 'FFC00000'}}), alignment: {horizontal: 'center', vertical: 'middle'}});\r\n      ws.getRow(3).height = 16;\r\n    }\r\n\r\n    const yarim = /yarim/i.test(J.period);\r\n    const heads = ['t/r', 'F.I.Sh.', ...R.L.map((c) => c.title), 'Jami ball', yarim ? 'Yarim yillik baho' : J.period === 'Yillik' ? 'Yillik baho' : 'Choraklik baho'];\r\n    const hrow = ws.getRow(4);\r\n    heads.forEach((t, i) => Object.assign(hrow.getCell(i + 1), {value: t, font: f({bold: true, size: 11}), alignment: {horizontal: 'center', vertical: 'middle', wrapText: true}, border: BOX}));\r\n    hrow.height = 64;\r\n\r\n    const r0 = 5;\r\n    const rN = r0 + R.rows.length - 1;\r\n    R.rows.forEach((r, k) => {\r\n      const n = r0 + k;\r\n      const row = ws.getRow(n);\r\n      row.getCell(1).value = k + 1;\r\n      row.getCell(2).value = r.name;\r\n      r.vals.forEach((v, i) => (row.getCell(3 + i).value = v == null ? null : v));\r\n      const tc = colL(cTot - 1) + n;\r\n      if (r.tot != null) {\r\n        row.getCell(cTot).value = {formula: `SUM(C${n}:${colL(cTot - 2)}${n})`, result: r.tot};\r\n        if (R.full) row.getCell(cG).value = {formula: `IF(${tc}=\"\",\"\",IF(${tc}<31,2,IF(${tc}<66,3,IF(${tc}<86,4,5))))`, result: r.g};\r\n      }\r\n      for (let c = 1; c <= cG; c++) {\r\n        const x = row.getCell(c);\r\n        x.font = f({bold: c >= cTot});\r\n        x.border = BOX;\r\n        x.alignment = {horizontal: c === 2 ? 'left' : 'center', vertical: 'middle'};\r\n        if (r.g) x.fill = {type: 'pattern', pattern: 'solid', fgColor: {argb: 'FF' + FILL[r.g]}};\r\n      }\r\n      row.height = 17;\r\n    });\r\n    // o'rtacha qator\r\n    const av = ws.getRow(rN + 1);\r\n    for (let c = 1; c <= cG; c++) {\r\n      const x = av.getCell(c);\r\n      if (c >= 3 && R.rows.length) {\r\n        const L = colL(c - 1);\r\n        const vals = c <= cTot - 1 ? R.rows.map((r) => r.vals[c - 3]) : c === cTot ? R.rows.map((r) => r.tot) : R.rows.map((r) => r.g || null);\r\n        const nn = vals.filter((v) => v != null);\r\n        const res = nn.length ? Math.round((nn.reduce((a, v) => a + v, 0) / nn.length) * 100) / 100 : '';\r\n        x.value = {formula: `IFERROR(ROUND(AVERAGE(${L}${r0}:${L}${rN}),2),\"\")`, result: res};\r\n      }\r\n      x.font = f({bold: true});\r\n      x.border = BOX;\r\n      x.alignment = {horizontal: 'center', vertical: 'middle'};\r\n    }\r\n    av.getCell(2).value = \"O'rtacha\";\r\n    // baholar soni va imzolar\r\n    const gL = colL(cG - 1);\r\n    const s0 = rN + 3;\r\n    // C–D ustunlarida baholar soni turadi, imzolar E dan o'ngda bo'lsin (tor jadvalda ustma-ust tushmasin)\r\n    const sigC = Math.max(5, cG - 3);\r\n    const nameC = Math.max(sigC + 2, cG - 1);\r\n    ws.getCell(`B${s0}`).value = 'Jami baholar:';\r\n    ws.getCell(`B${s0}`).font = f({bold: true});\r\n    ws.getCell(`B${s0}`).alignment = {horizontal: 'right'};\r\n    [5, 4, 3, 2].forEach((g, i) => {\r\n      const lab = ws.getCell(`C${s0 + i}`);\r\n      lab.value = `“${g}” baholar:`;\r\n      lab.font = f({size: 11});\r\n      lab.fill = {type: 'pattern', pattern: 'solid', fgColor: {argb: 'FF' + FILL[g]}};\r\n      const v = ws.getCell(`D${s0 + i}`);\r\n      v.value = {formula: `COUNTIF(${gL}${r0}:${gL}${rN},${g})&\" ta\"`, result: `${R.cnt[g]} ta`};\r\n      v.font = f({bold: true, size: 11});\r\n    });\r\n    [['O‘.I.B.D.O‘ :', cfg.ibdo], ['Metod birlashma:', cfg.metod], ['O‘qituvchi :', J.sign]].forEach(([t, v], i) => {\r\n      const rr = s0 + i * 2;\r\n      ws.getCell(rr, sigC).value = t;\r\n      ws.getCell(rr, sigC).font = f({size: 11});\r\n      const n = ws.getCell(rr, nameC);\r\n      n.value = v || '';\r\n      n.font = f({bold: true, size: 11});\r\n      n.border = {bottom: thin};\r\n      if (nameC + 1 <= cG) ws.getCell(rr, nameC + 1).border = {bottom: thin};\r\n    });\r\n    ws.pageSetup.printArea = `A1:${colL(Math.max(cG, nameC) - 1)}${s0 + 5}`;\r\n  }\r\n\r\n  async function download() {\r\n    if (!window.ExcelJS) throw new Error('ExcelJS yuklanmadi');\r\n    const wb = new ExcelJS.Workbook();\r\n    const used = new Set();\r\n    JOBS.forEach((J) => sheetFor(wb, J, used));\r\n    const buf = await wb.xlsx.writeBuffer();\r\n    const p = JOBS.length === 1 ? `${JOBS[0].cls}_${JOBS[0].sub}_${JOBS[0].period}` : `${JOBS[0].period}_${JOBS.length}_sinf`;\r\n    const name = `Natijalar_${p}.xlsx`.replace(/[\\\\/:*?\"<>|\\s]+/g, '_');\r\n    const a = document.createElement('a');\r\n    a.href = URL.createObjectURL(new Blob([buf], {type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));\r\n    a.download = name;\r\n    document.body.appendChild(a);\r\n    a.click();\r\n    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1500);\r\n    if (ADM.onDownload) ADM.onDownload(JOBS.length);\r\n  }\r\n\r\n  /* ================= Sifat tahlili (faqat admin) ================= */\r\n  // Jurnaldagi har bir BSB/ChSB ishi uchun: o'quvchi foizi = ball / maksimal ball → baho (chegaralar sozlanadi).\r\n  // Sifat = «5» va «4» olganlar ulushi, o'zlashtirish = «5», «4», «3» olganlar ulushi (ish yozganlar ichida).\r\n\r\n  const SF_COL = ['#1f77b4', '#ff7f0e', '#2ca02c', '#d62728', '#9467bd', '#8c564b'];\r\n  const sfCfg = Object.assign({th: [86, 71, 55], metric: 'sifat', chart: 'v', arrows: true, title: '', teacher: '', period: '', note: '', noteAuto: true}, ls.get('adm_sf_cfg', {}));\r\n  const sfSave = () => ls.set('adm_sf_cfg', sfCfg);\r\n  const p1 = (x) => (Math.round(x * 10) / 10).toFixed(1);\r\n  const pc1 = (x) => p1(x).replace('.', ',') + '%';\r\n\r\n  function sfData() {\r\n    const th = sfCfg.th.map(Number);\r\n    const gr = (p) => (p >= th[0] ? 5 : p >= th[1] ? 4 : p >= th[2] ? 3 : 2);\r\n    const series = []; // [{key, label, kind, n}]\r\n    const used = new Map();\r\n    const classes = JOBS.map((J) => {\r\n      const cnt = {bsb: 0, chsb: 0};\r\n      const vals = {};\r\n      J.cols.forEach((c, i) => {\r\n        if (c.kind !== 'bsb' && c.kind !== 'chsb') return;\r\n        const n = ++cnt[c.kind];\r\n        const key = c.kind + n;\r\n        if (!series.find((s) => s.key === key)) series.push({key, kind: c.kind, n, label: `${roman(n)}-${c.kind === 'bsb' ? 'BSB' : 'ChSB'}`});\r\n        const g = {5: 0, 4: 0, 3: 0, 2: 0};\r\n        let w = 0;\r\n        J.rows.forEach((r) => {\r\n          const v = r.v[i];\r\n          if (v == null || !c.max) return;\r\n          w++;\r\n          g[gr((v / c.max) * 100)]++;\r\n        });\r\n        if (w) vals[key] = {w, g, sifat: ((g[5] + g[4]) / w) * 100, ozl: ((g[5] + g[4] + g[3]) / w) * 100};\r\n      });\r\n      let label = J.cls || 'Sinf';\r\n      used.set(label, (used.get(label) || 0) + 1);\r\n      return {J, label, vals};\r\n    });\r\n    classes.forEach((c) => { if (used.get(c.label) > 1 && c.J.sub) c.label = `${c.label} (${c.J.sub})`; });\r\n    series.sort((a, b) => (a.kind === b.kind ? a.n - b.n : a.kind === 'bsb' ? -1 : 1));\r\n    const m = sfCfg.metric === 'ozl' ? 'ozl' : 'sifat';\r\n    classes.forEach((c) => { c.v = series.map((s) => (c.vals[s.key] ? c.vals[s.key][m] : null)); });\r\n    return {series, classes, m};\r\n  }\r\n\r\n  const sfPeriod = () => sfCfg.period || (JOBS[0] && JOBS[0].period) || 'I-chorak';\r\n  const sfMetricName = (D) => (D.m === 'ozl' ? \"O'ZLASHTIRISH\" : 'SIFAT SAMARADORLIGI');\r\n  const sfTitle = (D) => sfCfg.title || `${sfMetricName(D)} KO'RSATKICHLARI`;\r\n  const sfTeacher = () => sfCfg.teacher || (JOBS[0] && JOBS[0].teacher) || '';\r\n  const andJoin = (a) => (a.length < 2 ? a.join('') : a.slice(0, -1).join(', ') + ' va ' + a[a.length - 1]);\r\n\r\n  // Raqamlarga qarab metodik xulosa (AI'siz, qoidalar bo'yicha)\r\n  function sfAutoNote(D) {\r\n    if (!D.classes.length || !D.series.length) return '';\r\n    const per = sfPeriod().replace(/^I-/, '1-').replace(/^II-/, '2-').replace(/^III-/, '3-').replace(/^IV-/, '4-');\r\n    const what = D.m === 'ozl' ? \"o'zlashtirish\" : 'sifat';\r\n    const avg = (c) => { const a = c.v.filter((x) => x != null); return a.length ? a.reduce((s, x) => s + x, 0) / a.length : null; };\r\n    const low = D.classes.filter((c) => c.v.some((x) => x != null && x < 70)).map((c) => c.label);\r\n    const high = D.classes.filter((c) => !low.includes(c.label) && (c.v.some((x) => x === 100) || (avg(c) || 0) >= 85)).map((c) => c.label);\r\n    const mid = D.classes.filter((c) => !low.includes(c.label) && !high.includes(c.label)).map((c) => c.label);\r\n    const up = [], down = [];\r\n    D.classes.forEach((c) => {\r\n      const a = c.v.filter((x) => x != null);\r\n      if (a.length < 2) return;\r\n      const d = a[a.length - 1] - a[0];\r\n      if (d >= 5) up.push(`${c.label} (+${p1(d).replace('.', ',')}%)`);\r\n      if (d <= -5) down.push(`${c.label} (${p1(d).replace('.', ',')}%)`);\r\n    });\r\n    let s = `Monitoring va ${per} yakuniy natijalari tahliliga ko'ra`;\r\n    const parts = [];\r\n    if (low.length) parts.push(`${andJoin(low)} ${low.length > 1 ? 'sinflarida' : 'sinfida'} ${what} ko'rsatkichlarini yanada yaxshilash maqsadida bo'sh o'zlashtiruvchi o'quvchilar bilan individual va qo'shimcha mashg'ulotlarni to'g'ri tashkil etish lozim`);\r\n    if (mid.length) parts.push(`${andJoin(mid)} ${mid.length > 1 ? 'sinflarida' : 'sinfida'} ko'rsatkichlar yaxshi darajada bo'lib, ularni yanada oshirish uchun mavzular bo'yicha takrorlash va mustahkamlash ishlarini davom ettirish maqsadga muvofiq`);\r\n    if (high.length) parts.push(`${andJoin(high)} ${high.length > 1 ? 'sinflarida' : 'sinfida'} qayd etilgan yuqori ko'rsatkichlarni barqaror saqlab qolish, shuningdek, ChSB imtihonlariga tizimli tayyorgarlik ko'rish uchun iqtidorli o'quvchilar bilan individual fan olimpiadalari va chuqurlashtirilgan yo'nalishlarda ishlarni yanada jonlantirish tavsiya etiladi`);\r\n    s += ', ' + parts.join('. ') + '.';\r\n    if (up.length) s += ` Ijobiy dinamika kuzatildi: ${andJoin(up)}.`;\r\n    if (down.length) s += ` Pasayish kuzatilgan ${down.length > 1 ? 'sinflar' : 'sinf'}: ${andJoin(down)} — sabablarini tahlil qilib, bartaraf etish choralarini ko'rish lozim.`;\r\n    return s;\r\n  }\r\n\r\n  // Diagramma: (x,y,w,h) ichiga chiziladi. horiz=true — yotiq chiziqlar.\r\n  function sfChart(ctx, x, y, w, h, D, horiz, sub) {\r\n    const F = (sz, b) => `${b ? '600 ' : ''}${sz}px Segoe UI, Arial, sans-serif`;\r\n    ctx.save();\r\n    ctx.fillStyle = '#fff';\r\n    ctx.fillRect(x, y, w, h);\r\n    ctx.fillStyle = '#222';\r\n    ctx.textAlign = 'center';\r\n    ctx.textBaseline = 'alphabetic';\r\n    ctx.font = F(12.5);\r\n    ctx.fillText(`${sfMetricName(D)} KO'RSATKICHLARI${horiz ? '' : ' DINAMIKASI'}`, x + w / 2, y + 16);\r\n    ctx.fillText(sub, x + w / 2, y + 32);\r\n    const S = D.series, C = D.classes, ns = Math.max(1, S.length), nc = Math.max(1, C.length);\r\n    if (!horiz) {\r\n      const L = x + 48, R = x + w - 10, T = y + 66, B = y + h - 24;\r\n      const top = 115, Y = (v) => B - (v / top) * (B - T);\r\n      ctx.strokeStyle = '#333'; ctx.lineWidth = 1; ctx.strokeRect(L, T, R - L, B - T);\r\n      ctx.font = F(10); ctx.fillStyle = '#333'; ctx.textAlign = 'right'; ctx.textBaseline = 'middle';\r\n      for (let v = 0; v <= 100; v += 20) { ctx.fillText(v, L - 6, Y(v)); ctx.beginPath(); ctx.moveTo(L - 3, Y(v)); ctx.lineTo(L, Y(v)); ctx.stroke(); }\r\n      ctx.save(); ctx.translate(x + 12, (T + B) / 2); ctx.rotate(-Math.PI / 2); ctx.textAlign = 'center'; ctx.fillText('Foiz (%)', 0, 0); ctx.restore();\r\n      const gw = (R - L) / nc, bw = Math.min(46, (gw * 0.78) / ns);\r\n      C.forEach((c, i) => {\r\n        const cx = L + gw * (i + 0.5), x0 = cx - (bw * ns) / 2;\r\n        S.forEach((s, k) => {\r\n          const v = c.v[k];\r\n          if (v == null) return;\r\n          ctx.fillStyle = SF_COL[k % SF_COL.length];\r\n          ctx.fillRect(x0 + k * bw, Y(v), bw, B - Y(v));\r\n          ctx.fillStyle = '#222'; ctx.font = F(8.5); ctx.textAlign = 'center'; ctx.textBaseline = 'bottom';\r\n          ctx.fillText(p1(v) + '%', x0 + k * bw + bw / 2, Y(v) - 3);\r\n        });\r\n        ctx.fillStyle = '#222'; ctx.font = F(10.5); ctx.textAlign = 'center'; ctx.textBaseline = 'top';\r\n        ctx.fillText(c.label, cx, B + 6);\r\n      });\r\n      // legend (diagramma ustida, o'rtada — ustunlarni yopmasin)\r\n      ctx.font = F(10);\r\n      const items = S.map((s) => ctx.measureText(s.label).width + 40);\r\n      let lx = x + (w - items.reduce((a, b) => a + b, 0)) / 2;\r\n      S.forEach((s, k) => {\r\n        ctx.fillStyle = SF_COL[k % SF_COL.length]; ctx.fillRect(lx, y + 46, 22, 8);\r\n        ctx.fillStyle = '#222'; ctx.textAlign = 'left'; ctx.textBaseline = 'middle'; ctx.fillText(s.label, lx + 28, y + 50);\r\n        lx += items[k];\r\n      });\r\n    } else {\r\n      ctx.font = F(10.5);\r\n      const lab = Math.max(30, ...C.map((c) => ctx.measureText(c.label).width));\r\n      const L = x + lab + 18, R = x + w - 50, T = y + 46, B = y + h - 44;\r\n      const X = (v) => L + (v / 100) * (R - L);\r\n      ctx.font = F(9.5); ctx.textAlign = 'center'; ctx.textBaseline = 'top';\r\n      for (let v = 0; v <= 100; v += 20) {\r\n        ctx.strokeStyle = '#e5e5e5'; ctx.setLineDash([3, 3]); ctx.beginPath(); ctx.moveTo(X(v), T); ctx.lineTo(X(v), B); ctx.stroke(); ctx.setLineDash([]);\r\n        ctx.fillStyle = '#666'; ctx.fillText(v + '%', X(v), B + 5);\r\n      }\r\n      const gh = (B - T) / nc, bh = Math.min(16, (gh * 0.8) / ns);\r\n      C.forEach((c, i) => {\r\n        const cy = T + gh * (i + 0.5), y0 = cy - (bh * ns) / 2;\r\n        S.forEach((s, k) => {\r\n          const v = c.v[k];\r\n          if (v == null) return;\r\n          ctx.fillStyle = SF_COL[k % SF_COL.length];\r\n          ctx.fillRect(L, y0 + k * bh + 1, X(v) - L, bh - 2);\r\n          ctx.fillStyle = '#222'; ctx.font = F(8.5); ctx.textAlign = 'left'; ctx.textBaseline = 'middle';\r\n          ctx.fillText(p1(v) + '%', X(v) + 5, y0 + k * bh + bh / 2);\r\n        });\r\n        ctx.fillStyle = '#222'; ctx.font = F(10.5); ctx.textAlign = 'right'; ctx.textBaseline = 'middle';\r\n        ctx.fillText(c.label, L - 8, cy);\r\n      });\r\n      // legend (pastda, o'rtada)\r\n      ctx.font = F(10);\r\n      const items = S.map((s) => ctx.measureText(s.label).width + 40);\r\n      let lx = x + (w - items.reduce((a, b) => a + b, 0)) / 2;\r\n      const ly = B + 26;\r\n      S.forEach((s, k) => {\r\n        ctx.fillStyle = SF_COL[k % SF_COL.length]; ctx.fillRect(lx, ly - 4, 22, 8);\r\n        ctx.fillStyle = '#222'; ctx.textAlign = 'left'; ctx.textBaseline = 'middle'; ctx.fillText(s.label, lx + 28, ly);\r\n        lx += items[k];\r\n      });\r\n    }\r\n    ctx.restore();\r\n  }\r\n\r\n  function wrapText(ctx, text, maxW, first) {\r\n    const words = String(text).split(/\\s+/).filter(Boolean), lines = [];\r\n    let cur = '', lim = maxW - (first || 0);\r\n    words.forEach((wd) => {\r\n      const t = cur ? cur + ' ' + wd : wd;\r\n      if (ctx.measureText(t).width > lim && cur) { lines.push(cur); cur = wd; lim = maxW; } else cur = t;\r\n    });\r\n    if (cur) lines.push(cur);\r\n    return lines;\r\n  }\r\n\r\n  // To'liq A4 sahifa (827 x 1169 birlik, sc marta kattalashtirilgan)\r\n  function sfPage(D, note, sc) {\r\n    const W = 827, H = 1169, M = 62, CW = W - 2 * M;\r\n    const cv = document.createElement('canvas');\r\n    cv.width = W * sc; cv.height = H * sc;\r\n    const ctx = cv.getContext('2d');\r\n    ctx.scale(sc, sc);\r\n    const F = (sz, b) => `${b ? '700 ' : ''}${sz}px Segoe UI, Arial, sans-serif`;\r\n    const BLUE = '#1f4e79';\r\n    ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);\r\n    let y = 58;\r\n    if (cfg.school) { ctx.font = F(10); ctx.fillStyle = '#666'; ctx.textAlign = 'center'; ctx.fillText(cfg.school, W / 2, y - 22); }\r\n    ctx.textAlign = 'center'; ctx.fillStyle = BLUE; ctx.font = F(17, true); ctx.fillText(sfTitle(D), W / 2, y);\r\n    const subj = [...new Set(JOBS.map((J) => J.sub).filter(Boolean))].join(', ');\r\n    ctx.font = F(11); ctx.fillStyle = '#555';\r\n    ctx.fillText(`${sfPeriod()} hisoboti bo'yicha tahliliy hujjat${subj ? ' · ' + subj : ''}`, W / 2, y + 22);\r\n    y += 42;\r\n    const ch = Math.max(330, Math.min(420, 140 + D.classes.length * D.series.length * 18));\r\n    sfChart(ctx, M, y, CW, ch, D, sfCfg.chart === 'h', `${sfPeriod()} sinflar bo'yicha taqqoslama diagramma`);\r\n    y += ch + 30;\r\n    const sec = (t) => {\r\n      ctx.font = F(13, true); ctx.fillStyle = BLUE; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.fillText(t, M, y);\r\n      ctx.fillStyle = BLUE; ctx.fillRect(M, y + 8, CW, 1.6); y += 18;\r\n    };\r\n    sec('Natijalar jadvali');\r\n    const cols = ['Sinf', ...D.series.map((s) => s.label)];\r\n    const rh = D.classes.length > 14 ? 22 : 30, cw0 = Math.min(160, CW / cols.length), cwr = (CW - cw0) / Math.max(1, cols.length - 1);\r\n    const cx = (i) => (i === 0 ? M : M + cw0 + (i - 1) * cwr), cwd = (i) => (i === 0 ? cw0 : cwr);\r\n    const row = (cells, bg, bold, color) => {\r\n      cells.forEach((t, i) => {\r\n        ctx.fillStyle = bg; ctx.fillRect(cx(i), y, cwd(i), rh);\r\n        ctx.strokeStyle = '#cfcfcf'; ctx.lineWidth = 0.8; ctx.strokeRect(cx(i), y, cwd(i), rh);\r\n        const tx = typeof t === 'object' ? t : {t};\r\n        ctx.font = F(11, bold || i === 0); ctx.fillStyle = color || '#333'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\r\n        const mid = cx(i) + cwd(i) / 2;\r\n        ctx.fillText(tx.t, mid - (tx.a ? 6 : 0), y + rh / 2);\r\n        if (tx.a) { const tw = ctx.measureText(tx.t).width; ctx.fillStyle = tx.a === '↑' ? '#16a34a' : '#dc2626'; ctx.font = F(11, true); ctx.fillText(tx.a, mid + tw / 2 + 2, y + rh / 2); }\r\n      });\r\n      y += rh;\r\n    };\r\n    row(cols, '#f2f4f7', true, BLUE);\r\n    D.classes.forEach((c, r) => {\r\n      let prev = null;\r\n      row([c.label, ...c.v.map((v) => {\r\n        if (v == null) return '—';\r\n        const a = sfCfg.arrows && prev != null && Math.abs(v - prev) >= 0.05 ? (v > prev ? '↑' : '↓') : '';\r\n        prev = v;\r\n        return {t: pc1(v), a};\r\n      })], r % 2 ? '#fbfaff' : '#fff');\r\n    });\r\n    y += 30;\r\n    sec('Metodik xulosa');\r\n    ctx.font = F(11);\r\n    const pre = 'Xulosa: ';\r\n    ctx.font = F(11, true); const pw = ctx.measureText(pre).width; ctx.font = F(11);\r\n    const lines = wrapText(ctx, note || '', CW - 36, pw);\r\n    const lh = 17, bh = lines.length * lh + 26;\r\n    ctx.fillStyle = '#f7f8fc'; ctx.fillRect(M, y, CW, bh);\r\n    ctx.fillStyle = BLUE; ctx.fillRect(M, y, 4, bh);\r\n    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';\r\n    lines.forEach((l, i) => {\r\n      let lx = M + 20;\r\n      if (i === 0) { ctx.font = F(11, true); ctx.fillStyle = '#222'; ctx.fillText(pre, lx, y + 22); lx += pw; }\r\n      ctx.font = F(11); ctx.fillStyle = '#333'; ctx.fillText(l, lx, y + 22 + i * lh);\r\n    });\r\n    y += bh + 50;\r\n    ctx.font = F(11); ctx.fillStyle = '#333'; ctx.fillText('Fan o‘qituvchisi: ', M, y);\r\n    const tl = ctx.measureText('Fan o‘qituvchisi: ').width;\r\n    ctx.font = F(11, true); ctx.fillText(sfTeacher(), M + tl, y);\r\n    ctx.font = F(11, true); ctx.fillText('Imzo:', M + CW * 0.62, y);\r\n    ctx.fillStyle = '#555'; ctx.fillRect(M + CW * 0.62 + 40, y + 2, 140, 0.8);\r\n    return cv;\r\n  }\r\n\r\n  function saveBlob(blob, name) {\r\n    const a = document.createElement('a');\r\n    a.href = URL.createObjectURL(blob);\r\n    a.download = name.replace(/[\\\\/:*?\"<>|\\s]+/g, '_');\r\n    document.body.appendChild(a);\r\n    a.click();\r\n    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1500);\r\n  }\r\n\r\n  function Sifat(box) {\r\n    box.appendChild(h(`\r\n      <div class=\"card\">\r\n        <h2>Sifat tahlili</h2>\r\n        <p class=\"mut\" style=\"margin:-6px 0 14px\">eMaktab «Fan jurnali» fayllarini tashlang (Natijalar jadvaliga tashlanganlar shu yerda ham ishlaydi). Har bir BSB/ChSB uchun sifat foizi ballarga qarab avtomatik hisoblanadi.</p>\r\n        <label class=\"drop\" id=\"drop\"><input type=\"file\" id=\"fi\" accept=\".xls,.xlsx\" multiple hidden>\r\n          <b>Jurnal fayllarini shu yerga tashlang</b><span class=\"mut\">yoki bosib tanlang (har bir sinf — alohida fayl)</span></label>\r\n        <div id=\"err\" class=\"err\"></div>\r\n      </div>`));\r\n    box.appendChild(h('<div id=\"sfb\"></div>'));\r\n    const $ = (s) => box.querySelector(s);\r\n    const drop = $('#drop');\r\n    drop.ondragover = (e) => { e.preventDefault(); drop.classList.add('ov'); };\r\n    drop.ondragleave = () => drop.classList.remove('ov');\r\n    drop.ondrop = async (e) => { e.preventDefault(); drop.classList.remove('ov'); $('#err').textContent = await readJournals([...e.dataTransfer.files]); draw(); };\r\n    $('#fi').onchange = async (e) => { $('#err').textContent = await readJournals([...e.target.files]); e.target.value = ''; draw(); };\r\n\r\n    function draw() {\r\n      const b = $('#sfb');\r\n      b.innerHTML = '';\r\n      if (!JOBS.length) return;\r\n      const D = sfData();\r\n      if (sfCfg.noteAuto || !sfCfg.note) { sfCfg.note = sfAutoNote(D); sfCfg.noteAuto = true; }\r\n      const el = h(`\r\n        <div>\r\n          <div class=\"card\">\r\n            <div class=\"g4\">\r\n              <label>Ko'rsatkich<select data-k=\"metric\"><option value=\"sifat\">Sifat («5» + «4»)</option><option value=\"ozl\">O'zlashtirish («5» + «4» + «3»)</option></select></label>\r\n              <label>Diagramma<select data-k=\"chart\"><option value=\"v\">Tik ustunlar</option><option value=\"h\">Yotiq chiziqlar</option></select></label>\r\n              <label>Davr<input data-k=\"period\" placeholder=\"${esc((JOBS[0] && JOBS[0].period) || 'I-chorak')}\"></label>\r\n              <label>Fan o'qituvchisi<input data-k=\"teacher\" placeholder=\"${esc((JOBS[0] && JOBS[0].teacher) || '')}\"></label>\r\n              <label class=\"w2\">Sarlavha<input data-k=\"title\" placeholder=\"${esc(sfMetricName(D))} KO'RSATKICHLARI\"></label>\r\n              <label>Baho chegaralari: «5» / «4» / «3» (%)<span style=\"display:flex;gap:6px;margin-top:5px\"><input data-th=\"0\" inputmode=\"numeric\"><input data-th=\"1\" inputmode=\"numeric\"><input data-th=\"2\" inputmode=\"numeric\"></span></label>\r\n              <label style=\"display:flex;align-items:center;gap:8px;margin-top:22px\"><input type=\"checkbox\" data-k=\"arrows\" style=\"width:auto\"> O'zgarish strelkalari ↑↓</label>\r\n            </div>\r\n            <div class=\"tw\"><table class=\"pv\"><thead><tr><th>Sinf</th>${D.series.map((s) => `<th>${esc(s.label)}</th>`).join('')}<th></th></tr></thead><tbody>\r\n              ${D.classes.map((c, i) => `<tr><td><b>${esc(c.label)}</b><br><span class=\"mut\">${esc(c.J.sub || '')}</span></td>${D.series.map((s) => { const x = c.vals[s.key]; return x ? `<td><b>${pc1(D.m === 'ozl' ? x.ozl : x.sifat)}</b><br><span class=\"mut\">5:${x.g[5]} · 4:${x.g[4]} · 3:${x.g[3]} · 2:${x.g[2]} / ${x.w}</span></td>` : '<td>—</td>'; }).join('')}<td><button class=\"g sm\" data-x=\"${i}\">Olib tashlash</button></td></tr>`).join('')}\r\n            </tbody></table></div>\r\n            ${D.series.length ? '' : '<div class=\"err\">⚠ Jurnallarda BSB/ChSB ustunlari topilmadi. Natijalar jadvali bo‘limida ustun turlarini tekshiring.</div>'}\r\n            <p class=\"mut\" style=\"margin:10px 0 0\">Ustun turi noto'g'ri aniqlangan bo'lsa (masalan, Loyiha BSB deb olingan) — «Natijalar jadvali» bo'limida o'zgartiring.</p>\r\n          </div>\r\n          <div class=\"card\">\r\n            <h2>Metodik xulosa</h2>\r\n            <textarea id=\"note\" rows=\"5\" style=\"width:100%;font:inherit;color:var(--txt);background:var(--inp,#1c1c3c);border:1px solid var(--line);border-radius:10px;padding:10px\"></textarea>\r\n            <div style=\"display:flex;gap:8px;margin-top:8px;flex-wrap:wrap\"><button class=\"g sm\" id=\"reN\">↻ Raqamlarga qarab qayta yozish</button><span class=\"mut\" id=\"nst\" style=\"align-self:center\"></span></div>\r\n          </div>\r\n          <div class=\"card\">\r\n            <h2>Ko'rinishi</h2>\r\n            <div style=\"background:#fff;border-radius:8px;padding:8px;max-width:620px;margin:0 auto\"><img id=\"pv\" style=\"width:100%;display:block\"></div>\r\n          </div>\r\n          <div class=\"card bar2\"><div><b>Yuklab olish</b><div class=\"mut\">A4 hujjat, diagramma rasmi yoki Excel</div></div>\r\n            <div style=\"display:flex;gap:8px;flex-wrap:wrap\"><button id=\"dPdf\">PDF</button><button class=\"g\" id=\"dPng\">Diagramma (PNG)</button><button class=\"g\" id=\"dXl\">Excel</button></div></div>\r\n        </div>`);\r\n      b.appendChild(el);\r\n      const q = (s) => el.querySelector(s);\r\n      el.querySelectorAll('[data-k]').forEach((i) => {\r\n        const k = i.dataset.k;\r\n        if (i.type === 'checkbox') i.checked = !!sfCfg[k]; else i.value = sfCfg[k] || '';\r\n        i.onchange = () => { sfCfg[k] = i.type === 'checkbox' ? i.checked : i.value.trim(); sfSave(); draw(); };\r\n      });\r\n      el.querySelectorAll('[data-th]').forEach((i) => {\r\n        i.value = sfCfg.th[+i.dataset.th];\r\n        i.onchange = () => { const v = parseFloat(i.value); if (v > 0 && v <= 100) { sfCfg.th[+i.dataset.th] = v; sfSave(); } draw(); };\r\n      });\r\n      el.querySelectorAll('[data-x]').forEach((bt) => (bt.onclick = () => { JOBS.splice(+bt.dataset.x, 1); draw(); }));\r\n      const note = q('#note');\r\n      note.value = sfCfg.note;\r\n      q('#nst').textContent = sfCfg.noteAuto ? 'Avtomatik yozilgan — xohlasangiz tahrirlang' : \"Qo'lda tahrirlangan\";\r\n      let t;\r\n      note.oninput = () => { sfCfg.note = note.value; sfCfg.noteAuto = false; sfSave(); q('#nst').textContent = \"Qo'lda tahrirlangan\"; clearTimeout(t); t = setTimeout(preview, 400); };\r\n      q('#reN').onclick = () => { sfCfg.noteAuto = true; sfCfg.note = ''; sfSave(); draw(); };\r\n      const preview = () => { q('#pv').src = sfPage(D, sfCfg.note, 1.2).toDataURL('image/png'); };\r\n      preview();\r\n      const fname = (ext) => `Sifat_tahlili_${sfPeriod()}_${D.classes.length}_sinf.${ext}`;\r\n      q('#dPdf').onclick = () => {\r\n        if (!window.jspdf) { $('#err').textContent = 'PDF kutubxonasi yuklanmadi — sahifani yangilang.'; return; }\r\n        const cv = sfPage(D, sfCfg.note, 2.5);\r\n        const pdf = new jspdf.jsPDF({orientation: 'portrait', unit: 'mm', format: 'a4'});\r\n        pdf.addImage(cv.toDataURL('image/jpeg', 0.93), 'JPEG', 0, 0, 210, 297);\r\n        saveBlob(pdf.output('blob'), fname('pdf'));\r\n      };\r\n      q('#dPng').onclick = () => {\r\n        const sc = 2, w = 900, hh = Math.max(420, Math.min(560, 160 + D.classes.length * D.series.length * 22));\r\n        const cv = document.createElement('canvas'); cv.width = w * sc; cv.height = hh * sc;\r\n        const ctx = cv.getContext('2d'); ctx.scale(sc, sc);\r\n        sfChart(ctx, 0, 0, w, hh, D, sfCfg.chart === 'h', `${D.classes.map((c) => c.label).join(', ')} sinflari bo'yicha taqqoslama diagramma`);\r\n        cv.toBlob((bl) => saveBlob(bl, fname('png')), 'image/png');\r\n      };\r\n      q('#dXl').onclick = () => sfExcel(D, fname('xlsx')).catch((e) => { $('#err').textContent = 'Excel yaratib bo‘lmadi: ' + e.message; });\r\n    }\r\n    draw();\r\n  }\r\n\r\n  async function sfExcel(D, name) {\r\n    if (!window.ExcelJS) throw new Error('ExcelJS yuklanmadi');\r\n    const wb = new ExcelJS.Workbook();\r\n    const ws = wb.addWorksheet('Sifat tahlili', {pageSetup: {paperSize: 9, orientation: 'portrait', fitToPage: true, fitToWidth: 1, fitToHeight: 0}});\r\n    const n = D.series.length + 1, last = colL(Math.max(n, 6) - 1);\r\n    ws.columns = [{width: 16}, ...D.series.map(() => ({width: 14})), {width: 14}, {width: 14}, {width: 14}, {width: 14}];\r\n    const f = (o) => ({name: FONT, size: 12, ...o});\r\n    let r = 1;\r\n    if (cfg.school) { ws.mergeCells(`A${r}:${last}${r}`); Object.assign(ws.getCell(`A${r}`), {value: cfg.school, font: f({size: 11}), alignment: {horizontal: 'center'}}); r++; }\r\n    ws.mergeCells(`A${r}:${last}${r}`); Object.assign(ws.getCell(`A${r}`), {value: sfTitle(D), font: f({bold: true, size: 14, color: {argb: 'FF1F4E79'}}), alignment: {horizontal: 'center'}}); r++;\r\n    ws.mergeCells(`A${r}:${last}${r}`); Object.assign(ws.getCell(`A${r}`), {value: `${sfPeriod()} hisoboti bo'yicha tahliliy hujjat`, font: f({size: 11, italic: true}), alignment: {horizontal: 'center'}}); r += 2;\r\n    const hr = ws.getRow(r);\r\n    ['Sinf', ...D.series.map((s) => s.label)].forEach((t, i) => Object.assign(hr.getCell(i + 1), {value: t, font: f({bold: true}), alignment: {horizontal: 'center'}, border: BOX, fill: {type: 'pattern', pattern: 'solid', fgColor: {argb: 'FFF2F4F7'}}}));\r\n    r++;\r\n    D.classes.forEach((c) => {\r\n      const row = ws.getRow(r++);\r\n      row.getCell(1).value = c.label;\r\n      c.v.forEach((v, i) => (row.getCell(i + 2).value = v == null ? '—' : Math.round(v * 10) / 1000));\r\n      for (let i = 1; i <= n; i++) { const x = row.getCell(i); x.border = BOX; x.font = f({bold: i === 1}); x.alignment = {horizontal: 'center'}; if (i > 1) x.numFmt = '0.0%'; }\r\n    });\r\n    r++;\r\n    const img = document.createElement('canvas'); img.width = 1800; img.height = 900;\r\n    const ctx = img.getContext('2d'); ctx.scale(2, 2);\r\n    sfChart(ctx, 0, 0, 900, 450, D, sfCfg.chart === 'h', `${sfPeriod()} sinflar bo'yicha taqqoslama diagramma`);\r\n    const id = wb.addImage({base64: img.toDataURL('image/png'), extension: 'png'});\r\n    ws.addImage(id, {tl: {col: 0, row: r - 1}, ext: {width: 640, height: 320}});\r\n    r += 17;\r\n    ws.mergeCells(`A${r}:${last}${r}`); Object.assign(ws.getCell(`A${r}`), {value: 'Metodik xulosa', font: f({bold: true, color: {argb: 'FF1F4E79'}})}); r++;\r\n    ws.mergeCells(`A${r}:${last}${r + 5}`);\r\n    Object.assign(ws.getCell(`A${r}`), {value: 'Xulosa: ' + (sfCfg.note || ''), font: f({size: 11}), alignment: {wrapText: true, vertical: 'top'}});\r\n    r += 7;\r\n    ws.getCell(`A${r}`).value = `Fan o‘qituvchisi: ${sfTeacher()}`;\r\n    ws.getCell(`A${r}`).font = f({size: 11});\r\n    ws.getCell(`${colL(Math.max(n, 6) - 2)}${r}`).value = 'Imzo: ____________';\r\n    const buf = await wb.xlsx.writeBuffer();\r\n    saveBlob(new Blob([buf], {type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}), name);\r\n  }\r\n\r\n  /* ================= BSB va CHSB hisoboti (yillik) ================= */\r\n  // Har bir sinf + fan uchun BSB-1..4 va CHSB-1..4 foizlari (chorak bo'yicha). Jurnaldan o'zi olinadi, qo'lda tuzatsa bo'ladi.\r\n  // Foiz = sinfning o'rtacha bali / maksimal ball. Ma'lumot shu brauzerda saqlanadi (nj_hb).\r\n\r\n  const hb = Object.assign({title: '', year: '', teacher: '', rows: []}, ls.get('nj_hb', {}));\r\n  if (!Array.isArray(hb.rows)) hb.rows = [];\r\n  const hbSave = () => ls.set('nj_hb', hb);\r\n  const hbKey = (c, s) => (String(c).trim() + '|' + String(s).trim()).toLowerCase();\r\n  const hbSort = () => hb.rows.sort((a, b) => (parseInt(a.cls, 10) || 0) - (parseInt(b.cls, 10) || 0) || String(a.cls).localeCompare(String(b.cls)) || String(a.sub).localeCompare(String(b.sub)));\r\n  const hbNum = (v) => { const n = parseFloat(String(v).replace(',', '.').replace('%', '')); return isFinite(n) && n >= 0 && n <= 100 ? Math.round(n * 10) / 10 : null; };\r\n  const hbRow = (cls, sub) => ({cls, sub, bsb: [null, null, null, null], chsb: [null, null, null, null]});\r\n\r\n  // Jurnal -> jadval. Qaytaradi: {ok, text}\r\n  function hbFromJournal(J) {\r\n    const m = String(J.period).match(/^(IV|III|II|I)-/);\r\n    const q = m ? {I: 1, II: 2, III: 3, IV: 4}[m[1]] : 0;\r\n    if (!q) return {ok: false, text: `${J.file}: chorak aniqlanmadi (${J.period})`};\r\n    const pct = (kind) => {\r\n      const a = [];\r\n      J.cols.forEach((c, i) => {\r\n        if (c.kind !== kind || !c.max) return;\r\n        const v = J.rows.map((r) => r.v[i]).filter((x) => x != null);\r\n        if (v.length) a.push((v.reduce((s, x) => s + x, 0) / v.length / c.max) * 100);\r\n      });\r\n      return a.length ? Math.round((a.reduce((s, x) => s + x, 0) / a.length) * 10) / 10 : null;\r\n    };\r\n    const b = pct('bsb'), c = pct('chsb');\r\n    if (b == null && c == null) return {ok: false, text: `${J.file}: BSB/ChSB ballari topilmadi`};\r\n    let r = hb.rows.find((x) => hbKey(x.cls, x.sub) === hbKey(J.cls, J.sub));\r\n    if (!r) { r = hbRow(J.cls, J.sub); hb.rows.push(r); }\r\n    if (b != null) r.bsb[q - 1] = b;\r\n    if (c != null) r.chsb[q - 1] = c;\r\n    if (!hb.year && J.year) hb.year = J.year;\r\n    if (!hb.teacher && J.teacher) hb.teacher = shortName(J.teacher);\r\n    return {ok: true, text: `${J.cls} · ${J.sub} · ${q}-chorak: ${b != null ? 'BSB ' + b + '%' : ''}${b != null && c != null ? ', ' : ''}${c != null ? 'CHSB ' + c + '%' : ''}`};\r\n  }\r\n\r\n  // Bitta diagramma (namunadagi ko'rinish)\r\n  function hbChart(ctx, x, y, w, h, title, labels, vals) {\r\n    ctx.save();\r\n    ctx.fillStyle = '#fff'; ctx.fillRect(x, y, w, h);\r\n    ctx.strokeStyle = '#d4d4d4'; ctx.lineWidth = 0.8; ctx.strokeRect(x, y, w, h);\r\n    ctx.fillStyle = '#111'; ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';\r\n    ctx.font = '700 11.5px \"Times New Roman\", Times, serif';\r\n    ctx.fillText(title, x + w / 2, y + 18);\r\n    const L = x + 40, R = x + w - 10, T = y + 30, B = y + h - 30;\r\n    const Y = (v) => B - (v / 100) * (B - T);\r\n    ctx.font = '8px Arial, sans-serif'; ctx.textAlign = 'right'; ctx.textBaseline = 'middle';\r\n    for (let v = 0; v <= 100; v += 10) {\r\n      ctx.strokeStyle = v ? '#e3e3e3' : '#555'; ctx.lineWidth = v ? 0.6 : 0.9;\r\n      ctx.beginPath(); ctx.moveTo(L, Y(v)); ctx.lineTo(R, Y(v)); ctx.stroke();\r\n      ctx.fillStyle = '#333'; ctx.fillText(v + '%', L - 8, Y(v));\r\n    }\r\n    const sw = (R - L) / labels.length, bw = sw * 0.32;\r\n    labels.forEach((lb, i) => {\r\n      const cx = L + sw * (i + 0.5), v = vals[i];\r\n      if (v != null) {\r\n        ctx.fillStyle = '#7fb055'; ctx.fillRect(cx - bw / 2, Y(v), bw, B - Y(v));\r\n        ctx.strokeStyle = '#5c8f3a'; ctx.lineWidth = 0.8; ctx.strokeRect(cx - bw / 2, Y(v), bw, B - Y(v));\r\n        ctx.fillStyle = '#111'; ctx.font = '700 8.5px Arial, sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'bottom';\r\n        ctx.fillText(String(v), cx, Y(v) - 3);\r\n      }\r\n      ctx.fillStyle = '#111'; ctx.font = '700 8px Arial, sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'top';\r\n      ctx.fillText(lb, cx, B + 7);\r\n    });\r\n    ctx.restore();\r\n  }\r\n\r\n  // Hisobot betlari (yotiq A4: 842 x 595 birlik, sc marta kattalashtirilgan)\r\n  function hbPages(sc) {\r\n    const W = 842, H = 595, MX = 28;\r\n    const year = hb.year || '';\r\n    const head = hb.title || cfg.school || '';\r\n    const pages = [];\r\n    const page = (sub) => {\r\n      const cv = document.createElement('canvas');\r\n      cv.width = W * sc; cv.height = H * sc;\r\n      const ctx = cv.getContext('2d');\r\n      ctx.scale(sc, sc);\r\n      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);\r\n      ctx.fillStyle = '#000'; ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';\r\n      ctx.font = '700 12.5px Arial, sans-serif'; ctx.fillText(head, W / 2, 41);\r\n      ctx.font = '700 10.5px Arial, sans-serif'; ctx.fillText(sub, W / 2, 62);\r\n      pages.push(cv);\r\n      return ctx;\r\n    };\r\n    const charts = (kind, lab, sub) => {\r\n      const cw = 385, chh = 233, gx = 16, gy = 17, top = 79;\r\n      const L = [1, 2, 3, 4].map((n) => `${lab}-${n}`);\r\n      // diagramma betlariga faqat shu turda (BSB yoki CHSB) kamida bitta natijasi bor sinflar chiqadi\r\n      const list = hb.rows.filter((r) => r[kind].some((v) => v != null));\r\n      for (let i = 0; i < list.length; i += 4) {\r\n        const ctx = page(sub);\r\n        list.slice(i, i + 4).forEach((r, k) => hbChart(ctx, MX + (k % 2) * (cw + gx), top + Math.floor(k / 2) * (chh + gy), cw, chh, `${r.cls} sinf (${r.sub})`, L, r[kind]));\r\n      }\r\n    };\r\n    const pre = year ? `${year} o'quv ` : \"O'quv \";\r\n    charts('bsb', 'BSB', `${pre}yilining BSB natijalari`);\r\n    // jadval\r\n    const cols = ['Sinf', 'Fan', 'BSB-1', 'BSB-2', 'BSB-3', 'BSB-4', 'CHSB-1', 'CHSB-2', 'CHSB-3', 'CHSB-4'];\r\n    const wd = [45, 86, ...Array(8).fill((W - 2 * MX - 131) / 8)];\r\n    const xs = wd.map((_, i) => MX + wd.slice(0, i).reduce((s, v) => s + v, 0));\r\n    const rh = 19.5, perPage = 23;\r\n    for (let i = 0; i < Math.max(1, hb.rows.length); i += perPage) {\r\n      const ctx = page(`${pre}yilining BSB va CHSB natijalari jadvali`);\r\n      let y = 79;\r\n      const cellAt = (c, t, bg, bold, left) => {\r\n        ctx.fillStyle = bg; ctx.fillRect(xs[c], y, wd[c], rh);\r\n        ctx.strokeStyle = '#bdbdbd'; ctx.lineWidth = 0.7; ctx.strokeRect(xs[c], y, wd[c], rh);\r\n        ctx.fillStyle = '#111'; ctx.font = `${bold ? '700 ' : ''}8px Arial, sans-serif`; ctx.textBaseline = 'middle';\r\n        ctx.textAlign = left ? 'left' : 'center';\r\n        ctx.fillText(t, left ? xs[c] + 5 : xs[c] + wd[c] / 2, y + rh / 2 + 0.5);\r\n      };\r\n      cols.forEach((t, c) => cellAt(c, t, '#f7d674', true));\r\n      y += rh;\r\n      const part = hb.rows.slice(i, i + perPage);\r\n      part.forEach((r, k) => {\r\n        const bg = k % 2 ? '#fff' : '#fdf6e6';\r\n        cellAt(0, r.cls, '#ffff66', true);\r\n        cellAt(1, r.sub, bg, false, true);\r\n        r.bsb.concat(r.chsb).forEach((v, j) => cellAt(2 + j, v == null ? '' : String(v), bg));\r\n        y += rh;\r\n      });\r\n      if (hb.teacher && i + perPage >= hb.rows.length) {\r\n        y += 34;\r\n        ctx.fillStyle = '#111'; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';\r\n        ctx.font = '9.5px Arial, sans-serif'; ctx.fillText('Fan o‘qituvchisi:', MX, y);\r\n        ctx.font = '700 9.5px Arial, sans-serif'; ctx.fillText(hb.teacher, MX + 78, y);\r\n        ctx.font = '700 9.5px Arial, sans-serif'; ctx.fillText('Imzo:', W - MX - 190, y);\r\n        ctx.fillStyle = '#555'; ctx.fillRect(W - MX - 158, y + 2, 150, 0.8);\r\n      }\r\n    }\r\n    charts('chsb', 'CHSB', `${pre}yilidagi choraklik CHSB natijalari`);\r\n    return pages;\r\n  }\r\n\r\n  function Hisobot(box) {\r\n    box.innerHTML = `\r\n      <div class=\"card\">\r\n        <h2>Jurnal fayllarini yuklash</h2>\r\n        <p class=\"mut\" style=\"margin:-6px 0 14px\">eMaktab'dan har bir sinf va chorak uchun «Fan jurnali» Excel faylini tashlang. BSB va CHSB foizlari (sinfning o'rtacha bali) o'zi hisoblanib, jadvalga tushadi. Kiritilganlar shu kompyuterda saqlanadi — keyingi chorakda faqat yangi jurnallarni qo'shasiz.</p>\r\n        <div class=\"g3\">\r\n          <label>Sarlavha (maktab nomi)<input id=\"hT\" placeholder=\"5-umumiy o'rta ta'lim maktabi o'qituvchilari\"></label>\r\n          <label>O‘quv yili<input id=\"hY\" placeholder=\"2025-2026\"></label>\r\n          <label>Fan o‘qituvchisi (ixtiyoriy, imzo uchun)<input id=\"hN\" placeholder=\"A. Tursunov\"></label>\r\n        </div>\r\n        <label class=\"drop\" id=\"hDrop\"><input type=\"file\" id=\"hFi\" accept=\".xls,.xlsx\" multiple hidden>\r\n          <b>Jurnal fayllarini shu yerga tashlang</b><span class=\"mut\">yoki bosib tanlang (.xls, bir nechta bo'lishi mumkin)</span></label>\r\n        <div id=\"hMsg\"></div>\r\n      </div>\r\n      <div class=\"card\">\r\n        <div class=\"jh\" style=\"margin-bottom:10px\"><h2 style=\"margin:0\">Natijalar (foizda)</h2>\r\n          <div style=\"display:flex;gap:8px;flex-wrap:wrap\"><button class=\"g sm\" id=\"hAdd\">+ Qator qo'shish</button><button class=\"g sm dn\" id=\"hClr\">Hammasini tozalash</button></div></div>\r\n        <p class=\"mut\" style=\"margin:0 0 10px\">Istalgan katakni qo'lda yozish yoki tuzatish mumkin (0 dan 100 gacha). BSB-1 — 1-chorak, BSB-2 — 2-chorak va hokazo.</p>\r\n        <div class=\"tw\"><table class=\"hbt\"><thead><tr><th>Sinf</th><th>Fan</th>${[1, 2, 3, 4].map((n) => `<th>BSB-${n}</th>`).join('')}${[1, 2, 3, 4].map((n) => `<th>CHSB-${n}</th>`).join('')}<th></th></tr></thead><tbody id=\"hTb\"></tbody></table></div>\r\n      </div>\r\n      <div class=\"card hide\" id=\"hPvC\">\r\n        <h2>Ko'rinishi <span class=\"mut\" id=\"hPc\"></span></h2>\r\n        <div id=\"hPv\" style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:10px\"></div>\r\n      </div>\r\n      <div class=\"card bar2 hide\" id=\"hDl\"><div><b>Tayyor hisobot</b><div class=\"mut\">Yotiq A4, diagrammalar va umumiy jadval</div></div><button id=\"hPdf\">PDF yuklab olish</button></div>`;\r\n    const $ = (s) => box.querySelector(s);\r\n    const msg = (html) => { $('#hMsg').innerHTML = html; };\r\n    [['hT', 'title'], ['hY', 'year'], ['hN', 'teacher']].forEach(([id, k]) => {\r\n      const el = $('#' + id);\r\n      el.value = hb[k] || (k === 'title' ? cfg.school || '' : '');\r\n      el.oninput = () => { hb[k] = el.value.trim(); hbSave(); later(); };\r\n    });\r\n    let tm;\r\n    const later = () => { clearTimeout(tm); tm = setTimeout(preview, 450); };\r\n\r\n    function preview() {\r\n      const has = hb.rows.length > 0;\r\n      $('#hPvC').classList.toggle('hide', !has);\r\n      $('#hDl').classList.toggle('hide', !has);\r\n      if (!has) return;\r\n      const pg = hbPages(1.1);\r\n      $('#hPc').textContent = `(${pg.length} bet)`;\r\n      $('#hPv').innerHTML = pg.map((c) => `<img src=\"${c.toDataURL('image/png')}\" style=\"width:100%;display:block;border:1px solid var(--line);border-radius:8px;background:#fff\">`).join('');\r\n    }\r\n\r\n    function draw() {\r\n      hbSort();\r\n      const inp = (i, f, v, w, al) => `<input data-i=\"${i}\" data-f=\"${f}\" value=\"${esc(v == null ? '' : v)}\" style=\"width:${w}px;height:30px;padding:0 6px;text-align:${al || 'center'}\"${/^[bc]\\d$/.test(f) ? ' inputmode=\"decimal\"' : ''}>`;\r\n      $('#hTb').innerHTML = hb.rows.map((r, i) => `<tr><td>${inp(i, 'cls', r.cls, 62)}</td><td>${inp(i, 'sub', r.sub, 150, 'left')}</td>${r.bsb.map((v, j) => `<td>${inp(i, 'b' + j, v, 62)}</td>`).join('')}${r.chsb.map((v, j) => `<td>${inp(i, 'c' + j, v, 62)}</td>`).join('')}<td><button class=\"g sm dn\" data-del=\"${i}\" title=\"Qatorni o'chirish\">✕</button></td></tr>`).join('') || '<tr><td colspan=\"11\" class=\"mut\">Hali ma‘lumot yo‘q — yuqoriga jurnal faylini tashlang yoki «Qator qo‘shish» ni bosing.</td></tr>';\r\n      $('#hT').value = hb.title || cfg.school || '';\r\n      $('#hY').value = hb.year || '';\r\n      $('#hN').value = hb.teacher || '';\r\n      preview();\r\n    }\r\n\r\n    $('#hTb').onchange = (e) => {\r\n      const el = e.target.closest('input[data-f]');\r\n      if (!el) return;\r\n      const r = hb.rows[+el.dataset.i], f = el.dataset.f;\r\n      if (!r) return;\r\n      if (f === 'cls' || f === 'sub') r[f] = el.value.trim();\r\n      else {\r\n        const n = el.value.trim() === '' ? null : hbNum(el.value);\r\n        if (el.value.trim() !== '' && n == null) { el.style.borderColor = 'var(--bad)'; return; }\r\n        el.style.borderColor = '';\r\n        el.value = n == null ? '' : n;\r\n        (f[0] === 'b' ? r.bsb : r.chsb)[+f[1]] = n;\r\n      }\r\n      hbSave();\r\n      later();\r\n    };\r\n    box.onclick = (e) => {\r\n      const b = e.target.closest('button');\r\n      if (!b) return;\r\n      if (b.dataset.del) { hb.rows.splice(+b.dataset.del, 1); hbSave(); draw(); }\r\n    };\r\n    $('#hAdd').onclick = () => { hb.rows.push(hbRow('', '')); hbSave(); draw(); const a = box.querySelectorAll('input[data-f=\"cls\"]'); const emp = [...a].find((x) => !x.value); if (emp) emp.focus(); };\r\n    $('#hClr').onclick = () => { if (hb.rows.length && confirm('Jadvaldagi barcha natijalar o‘chiriladi. Davom etilsinmi?')) { hb.rows = []; hbSave(); msg(''); draw(); } };\r\n\r\n    async function addFiles(fl) {\r\n      const out = [];\r\n      for (const f of fl) {\r\n        try {\r\n          const wb = XLSX.read(await f.arrayBuffer(), {type: 'array'});\r\n          const aoa = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], {header: 1, defval: '', raw: true});\r\n          out.push(hbFromJournal(parseJournal(aoa, f.name)));\r\n        } catch (e) {\r\n          out.push({ok: false, text: `${f.name}: ${e.message}`});\r\n        }\r\n      }\r\n      hbSave();\r\n      msg(out.map((o) => `<div class=\"${o.ok ? 'ok' : 'err'}\">${o.ok ? '✓' : '⚠'} ${esc(o.text)}</div>`).join(''));\r\n      draw();\r\n    }\r\n    const drop = $('#hDrop');\r\n    drop.ondragover = (e) => { e.preventDefault(); drop.classList.add('ov'); };\r\n    drop.ondragleave = () => drop.classList.remove('ov');\r\n    drop.ondrop = (e) => { e.preventDefault(); drop.classList.remove('ov'); addFiles([...e.dataTransfer.files]); };\r\n    $('#hFi').onchange = (e) => { addFiles([...e.target.files]); e.target.value = ''; };\r\n\r\n    $('#hPdf').onclick = () => {\r\n      if (!window.jspdf) { msg('<div class=\"err\">PDF kutubxonasi yuklanmadi — sahifani yangilang.</div>'); return; }\r\n      const pdf = new jspdf.jsPDF({orientation: 'landscape', unit: 'mm', format: 'a4'});\r\n      hbPages(2.5).forEach((cv, i) => { if (i) pdf.addPage(); pdf.addImage(cv.toDataURL('image/jpeg', 0.93), 'JPEG', 0, 0, 297, 210); });\r\n      saveBlob(pdf.output('blob'), `BSB_CHSB_hisobot_${hb.year || 'yil'}.pdf`);\r\n      if (ADM.onDownload) ADM.onDownload(1);\r\n    };\r\n    draw();\r\n  }\r\n\r\n  /* ================= Obunachilar (faqat admin) ================= */\r\n\r\n  const DUR = {31: '1 oy', 92: '3 oy', 366: '1 yil'};\r\n  const show = (c) => (c.length === 10 ? `${c.slice(0, 2)}-${c.slice(2, 6)}-${c.slice(6)}` : c);\r\n  const daysLeft = (iso) => Math.ceil((Date.parse(iso) - Date.now()) / 864e5);\r\n\r\n  function Subs(box) {\r\n    box.innerHTML = `\r\n      <div class=\"card\">\r\n        <h2>Yangi kod yaratish</h2>\r\n        <p class=\"mut\" style=\"margin:-6px 0 12px\">O'qituvchi to'lov qilgach, «Bo'sh kodlar» ro'yxatidan bittasini nusxalab, unga Telegram'da yuboring. Kod birinchi kiritgan odamning Telegram akkauntiga bog'lanadi.</p>\r\n        <div style=\"display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end\">\r\n          <label style=\"width:160px\">Muddat<select id=\"gD\"><option value=\"31\">1 oy</option><option value=\"92\">3 oy</option><option value=\"366\">1 yil</option></select></label>\r\n          <label style=\"width:120px\">Nechta<input id=\"gN\" type=\"number\" min=\"1\" max=\"50\" value=\"5\"></label>\r\n          <button id=\"gB\">Yaratish</button>\r\n        </div>\r\n        <div id=\"gM\" class=\"mut\" style=\"margin-top:8px\"></div>\r\n      </div>\r\n      <div class=\"kp\" id=\"sK\"></div>\r\n      <div class=\"card\"><h2>Faol obunachilar <span class=\"mut\" id=\"cA\"></span></h2><div class=\"tw\"><table><thead><tr><th>O'qituvchi</th><th>Telegram</th><th>Kod</th><th>Muddat</th><th>Qachongacha</th><th>Qoldi</th><th></th></tr></thead><tbody id=\"tA\"></tbody></table></div></div>\r\n      <div class=\"card\"><h2>Bo'sh kodlar <span class=\"mut\" id=\"cF\"></span></h2><div class=\"tw\"><table><thead><tr><th>Kod</th><th>Muddat</th><th>Yaratilgan</th><th></th></tr></thead><tbody id=\"tF\"></tbody></table></div></div>\r\n      <div class=\"card\"><h2>Muddati tugagan va bekor qilingan <span class=\"mut\" id=\"cE\"></span></h2><div class=\"tw\"><table><thead><tr><th>Kod</th><th>O'qituvchi</th><th>Holat</th><th></th></tr></thead><tbody id=\"tE\"></tbody></table></div></div>`;\r\n    const $ = (s) => box.querySelector(s);\r\n    const who = (u) => (u ? esc([u.first, u.last].filter(Boolean).join(' ') || 'Ismsiz') : '—');\r\n    const tgl = (u) => (u && u.username ? `<a href=\"https://t.me/${esc(u.username)}\" target=\"_blank\" rel=\"noopener\">@${esc(u.username)}</a>` : `<span class=\"mut\">${u ? 'ID ' + esc(u.id) : ''}</span>`);\r\n    const copyBtn = (c) => `<button class=\"g sm\" data-cp=\"${esc(show(c))}\">Nusxalash</button>`;\r\n    async function load() {\r\n      const r = await ADM.api('codes');\r\n      if (!r.ok) { $('#gM').textContent = 'Ro‘yxatni olib bo‘lmadi'; return; }\r\n      const now = Date.now();\r\n      const all = r.codes;\r\n      const act = all.filter((c) => !c.revoked && c.user && Date.parse(c.until) > now).sort((a, b) => Date.parse(a.until) - Date.parse(b.until));\r\n      const free = all.filter((c) => !c.revoked && !c.user).sort((a, b) => (a.created < b.created ? 1 : -1));\r\n      const ended = all.filter((c) => c.revoked || (c.user && Date.parse(c.until) <= now)).sort((a, b) => ((a.revoked || a.until) < (b.revoked || b.until) ? 1 : -1));\r\n      $('#sK').innerHTML = `\r\n        <div class=\"card\"><div class=\"l\">Faol obunachilar</div><div class=\"n\" style=\"color:var(--xl)\">${act.length}</div></div>\r\n        <div class=\"card\"><div class=\"l\">Bo'sh kodlar</div><div class=\"n\">${free.length}</div><div class=\"mut\">1 oy: ${free.filter((c) => c.days === 31).length} · 3 oy: ${free.filter((c) => c.days === 92).length} · 1 yil: ${free.filter((c) => c.days === 366).length}</div></div>\r\n        <div class=\"card\"><div class=\"l\">Tugagan / bekor</div><div class=\"n\" style=\"color:var(--mut)\">${ended.length}</div></div>`;\r\n      $('#cA').textContent = `(${act.length})`;\r\n      $('#cF').textContent = `(${free.length})`;\r\n      $('#cE').textContent = `(${ended.length})`;\r\n      $('#tA').innerHTML = act.map((c) => { const d = daysLeft(c.until); return `<tr><td><b>${who(c.user)}</b></td><td>${tgl(c.user)}</td><td><code>${esc(show(c.code))}</code></td><td>${DUR[c.days] || c.days + ' kun'}</td><td>${esc(uzDate(c.until))}</td><td${d <= 5 ? ' style=\"color:var(--warn,#fbbf24);font-weight:700\"' : ''}>${d} kun</td><td style=\"white-space:nowrap\"><button class=\"g sm\" data-rl=\"${esc(c.code)}\" title=\"Kod bu akkauntdan uziladi, qolgan kunlar saqlanadi\">Bo'shatish</button> <button class=\"g sm dn\" data-rv=\"${esc(c.code)}\">Bekor qilish</button></td></tr>`; }).join('') || '<tr><td colspan=\"7\" class=\"mut\">Hali hech kim ulanmagan</td></tr>';\r\n      $('#tF').innerHTML = free.map((c) => `<tr><td><code class=\"big\">${esc(show(c.code))}</code>${c.left != null ? ` <span class=\"tag\">qolgan ${Math.ceil(c.left / 864e5)} kun</span>` : ''}</td><td>${DUR[c.days] || c.days + ' kun'}</td><td class=\"mut\">${esc(uzDate(c.created))}</td><td style=\"white-space:nowrap\">${copyBtn(c.code)} <button class=\"g sm dn\" data-rv=\"${esc(c.code)}\">O'chirish</button></td></tr>`).join('') || '<tr><td colspan=\"4\" class=\"mut\">Bo‘sh kod yo‘q — yuqorida yarating</td></tr>';\r\n      $('#tE').innerHTML = ended.map((c) => `<tr><td><code>${esc(show(c.code))}</code></td><td>${who(c.user)} ${c.user ? tgl(c.user) : ''}</td><td class=\"mut\">${c.revoked ? 'Bekor qilingan ' + esc(uzDate(c.revoked)) : 'Tugagan ' + esc(uzDate(c.until))}</td><td></td></tr>`).join('') || '<tr><td colspan=\"4\" class=\"mut\">Yo‘q</td></tr>';\r\n    }\r\n    box.onclick = async (e) => {\r\n      const b = e.target.closest('button');\r\n      if (!b) return;\r\n      if (b.dataset.cp) {\r\n        try { await navigator.clipboard.writeText(b.dataset.cp); b.textContent = 'Nusxalandi ✓'; } catch (err) { prompt('Kodni nusxalang:', b.dataset.cp); }\r\n        setTimeout(() => (b.textContent = 'Nusxalash'), 1500);\r\n        return;\r\n      }\r\n      if (b.dataset.rl && confirm(\"Kod bu o'qituvchidan uziladi. Qolgan kunlar saqlanadi va kodni qayta berish mumkin. Davom etilsinmi?\")) { await ADM.api('release', {code: b.dataset.rl}); load(); }\r\n      if (b.dataset.rv && confirm('Kod butunlay bekor qilinadi va endi ishlamaydi. Davom etilsinmi?')) { await ADM.api('revoke', {code: b.dataset.rv}); load(); }\r\n    };\r\n    $('#gB').onclick = async () => {\r\n      const n = Math.min(50, Math.max(1, +$('#gN').value || 1));\r\n      $('#gB').disabled = true;\r\n      $('#gM').textContent = 'Yaratilmoqda...';\r\n      const r = await ADM.api('gen', {days: +$('#gD').value, count: n});\r\n      $('#gB').disabled = false;\r\n      $('#gM').textContent = r.ok ? `${r.codes.length} ta yangi kod yaratildi (${DUR[+$('#gD').value]}).` : 'Yaratib bo‘lmadi';\r\n      load();\r\n    };\r\n    load();\r\n  }\r\n\r\n  /* ================= Tokenlar (faqat admin) ================= */\r\n\r\n  function Tokens(box) {\r\n    box.innerHTML = `\r\n      <div class=\"kp\" id=\"kK\"></div>\r\n      <div class=\"card\">\r\n        <h2>Token berish</h2>\r\n        <p class=\"mut\" style=\"margin:-6px 0 12px\">O'qituvchini toping va tugmani bosing — tokenlar darhol balansiga tushadi, kod yuborish shart emas. Xato bossangiz, pastda chiqadigan «Bekor qilish» ni bosing.</p>\r\n        <div style=\"display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:6px\">\r\n          <div class=\"srch\">${ic('search')}<input id=\"kQ\" placeholder=\"Ism, @username yoki Telegram ID\" autocomplete=\"off\"></div>\r\n          <button class=\"g\" id=\"kR\">Yangilash</button>\r\n        </div>\r\n        <div id=\"kM\" class=\"mut\"></div>\r\n        <div class=\"tl\" id=\"kL\"></div>\r\n      </div>\r\n      <details class=\"card\" id=\"kD\"><summary>${ic('chevron-right')}Kod orqali berish <span class=\"mut\" id=\"kcF\"></span></summary>\r\n        <p class=\"mut\" style=\"margin:0 0 12px\">Hali saytga kirmagan o'qituvchi uchun: kod yarating, nusxalab Telegram'da yuboring. O'qituvchi kabinetdagi «Kod kiritish» ga yozadi. Kod bir marta ishlaydi.</p>\r\n        <div style=\"display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;margin-bottom:12px\">\r\n          <label style=\"width:140px\">Necha token<input id=\"kN\" type=\"number\" min=\"1\" max=\"500\" value=\"20\"></label>\r\n          <label style=\"width:120px\">Nechta kod<input id=\"kC\" type=\"number\" min=\"1\" max=\"50\" value=\"1\"></label>\r\n          <button id=\"kB\">Kod yaratish</button>\r\n          <span id=\"kGM\" class=\"mut\"></span>\r\n        </div>\r\n        <div class=\"tw\"><table><thead><tr><th>Kod</th><th>Token</th><th>Yaratilgan</th><th></th></tr></thead><tbody id=\"ktF\"></tbody></table></div>\r\n      </details>\r\n      <details class=\"card\"><summary>${ic('chevron-right')}Ishlatilgan va bekor qilingan kodlar <span class=\"mut\" id=\"kcU\"></span></summary>\r\n        <div class=\"tw\"><table><thead><tr><th>Kod</th><th>Token</th><th>Kim</th><th>Holat</th></tr></thead><tbody id=\"ktU\"></tbody></table></div>\r\n      </details>`;\r\n    const $ = (s) => box.querySelector(s);\r\n    const nm = (u) => [u.first, u.last].filter(Boolean).join(' ') || 'Ismsiz';\r\n    const who = (u) => (u ? esc(nm(u)) : '—');\r\n    const tgl = (u) => (u && u.username ? `<a href=\"https://t.me/${esc(u.username)}\" target=\"_blank\" rel=\"noopener\">@${esc(u.username)}</a>` : `<span>${u ? 'ID ' + esc(u.id) : ''}</span>`);\r\n    const QUICK = [10, 20, 50, 100];\r\n    const MAXROWS = 40;\r\n    let AC = [];\r\n    let openId = null; // ochiq qator (boshqa son / tarix)\r\n    let openMode = '';\r\n    let HIST = null;\r\n\r\n    function toast(text, undo) {\r\n      const old = document.getElementById('toast');\r\n      if (old) old.remove();\r\n      const t = h(`<div id=\"toast\"><span>${esc(text)}</span>${undo ? '<button>Bekor qilish</button>' : ''}</div>`);\r\n      document.body.appendChild(t);\r\n      const tm = setTimeout(() => t.remove(), undo ? 9000 : 3500);\r\n      if (undo) t.querySelector('button').onclick = () => { clearTimeout(tm); t.remove(); undo(); };\r\n    }\r\n\r\n    function kpi(free) {\r\n      const sum = (a, f) => a.reduce((s, x) => s + (+f(x) || 0), 0);\r\n      $('#kK').innerHTML = `\r\n        <div class=\"card\"><div class=\"l\">O'qituvchilar</div><div class=\"n\">${AC.length}</div></div>\r\n        <div class=\"card\"><div class=\"l\">Balansdagi tokenlar</div><div class=\"n\" style=\"color:var(--warn)\">${sum(AC, (a) => a.bal)}</div></div>\r\n        <div class=\"card\"><div class=\"l\">Sarflangan</div><div class=\"n\" style=\"color:var(--xl)\">${sum(AC, (a) => a.spent)}</div></div>\r\n        <div class=\"card\"><div class=\"l\">Bo'sh kodlar</div><div class=\"n\">${free.length}</div><div class=\"mut\">${sum(free, (c) => c.n)} token</div></div>`;\r\n    }\r\n\r\n    function rows() {\r\n      const q = $('#kQ').value.trim().toLowerCase().replace(/^@/, '');\r\n      const list = q ? AC.filter((a) => (nm(a) + ' ' + (a.username || '') + ' ' + a.id).toLowerCase().includes(q)) : AC;\r\n      $('#kM').textContent = !AC.length ? '' : q ? `${list.length} ta topildi` : `Jami ${AC.length} ta o'qituvchi (oxirgi kirganlar yuqorida)`;\r\n      $('#kL').innerHTML = list.slice(0, MAXROWS).map((a) => {\r\n        const bal = a.bal || 0;\r\n        let sub = '';\r\n        if (openId === a.id && openMode === 'n') {\r\n          sub = `<div class=\"sub1\"><div class=\"f\">\r\n            <label style=\"width:130px\">Nechta token<input id=\"oN\" type=\"number\" min=\"-1000\" max=\"1000\" placeholder=\"masalan 30\"></label>\r\n            <label style=\"flex:1;min-width:180px\">Izoh (o'qituvchi tarixida ko'rinadi)<input id=\"oW\" maxlength=\"80\" placeholder=\"masalan: To'lov 20 000 so'm\"></label>\r\n            <button data-go=\"${esc(a.id)}\">Berish</button><button class=\"g\" data-cl=\"1\">Yopish</button></div>\r\n            <div class=\"mut\" style=\"margin-top:8px\">Ayirish uchun minus bilan yozing (masalan -5). Balans 0 dan pastga tushmaydi.</div></div>`;\r\n        } else if (openId === a.id && openMode === 'h') {\r\n          sub = `<div class=\"sub1\">${!HIST ? '<span class=\"mut\">Yuklanmoqda...</span>' : (HIST.length ? HIST.map((l) => `<div class=\"lg1\"><span>${esc(l.w)}</span><span><b class=\"${l.d > 0 ? 'pl' : 'mi'}\">${l.d > 0 ? '+' : ''}${esc(l.d)}</b> <span class=\"mut\">· ${esc(uzDate(l.t))}</span></span></div>`).join('') : '<span class=\"mut\">Tarix bo‘sh</span>')}\r\n            <div style=\"margin-top:10px\"><button class=\"g sm\" data-cl=\"1\">Yopish</button></div></div>`;\r\n        }\r\n        return `<div class=\"tr1\">\r\n          <div class=\"who\"><div class=\"av\">${esc((nm(a)[0] || '?').toUpperCase())}</div><div style=\"min-width:0\"><b>${who(a)}</b><span class=\"mut\">${tgl(a)} · ${esc(uzDate(a.created))} dan</span></div></div>\r\n          <div class=\"bal${bal ? '' : ' z'}\" title=\"Balans\">${ic('zap')}${esc(bal)}</div>\r\n          <div class=\"last mut\">${a.lastLog ? esc(a.lastLog.w) + ' · ' + esc(uzDate(a.lastLog.t)) : ''}<br>Sarflagan: ${esc(a.spent || 0)}</div>\r\n          <div class=\"qb\">${QUICK.map((n) => `<button class=\"g sm q\" data-q=\"${n}\" data-id=\"${esc(a.id)}\">+${n}</button>`).join('')}<button class=\"g sm\" data-on=\"${esc(a.id)}\">Boshqa</button><button class=\"g sm\" data-oh=\"${esc(a.id)}\">Tarix</button></div>\r\n          ${sub}</div>`;\r\n      }).join('') || `<div class=\"mut\" style=\"padding:14px 2px\">${AC.length ? 'Bunday o‘qituvchi topilmadi. U saytga hali Telegram orqali kirmagan bo‘lsa — pastdagi «Kod orqali berish» dan foydalaning.' : 'Hali hech kim saytga kirmagan.'}</div>`;\r\n      if (list.length > MAXROWS) $('#kL').insertAdjacentHTML('beforeend', `<div class=\"mut\" style=\"padding:10px 2px\">Yana ${list.length - MAXROWS} ta — qidiruvdan foydalaning.</div>`);\r\n    }\r\n\r\n    async function load() {\r\n      const [r, q] = await Promise.all([ADM.api('tkcodes'), ADM.api('tkaccts')]);\r\n      if (!r.ok || !q.ok) { $('#kM').textContent = 'Ro‘yxatni olib bo‘lmadi'; return; }\r\n      const free = r.codes.filter((c) => !c.revoked && !c.used).sort((a, b) => (a.created < b.created ? 1 : -1));\r\n      const used = r.codes.filter((c) => c.revoked || c.used).sort((a, b) => (((a.used && a.used.at) || a.revoked) < ((b.used && b.used.at) || b.revoked) ? 1 : -1));\r\n      AC = q.accts.sort((a, b) => ((a.lastSeen || '') < (b.lastSeen || '') ? 1 : -1));\r\n      kpi(free);\r\n      rows();\r\n      $('#kcF').textContent = `(bo'sh: ${free.length})`;\r\n      $('#kcU').textContent = `(${used.length})`;\r\n      $('#ktF').innerHTML = free.map((c) => `<tr><td><code class=\"big\">${esc(show(c.code))}</code></td><td><b>${esc(c.n)}</b></td><td class=\"mut\">${esc(uzDate(c.created))}</td><td style=\"text-align:right\"><button class=\"g sm\" data-cp=\"${esc(show(c.code))}\">Nusxalash</button> <button class=\"g sm dn\" data-kr=\"${esc(c.code)}\">O'chirish</button></td></tr>`).join('') || '<tr><td colspan=\"4\" class=\"mut\">Bo‘sh kod yo‘q — yuqorida yarating</td></tr>';\r\n      $('#ktU').innerHTML = used.map((c) => `<tr><td><code>${esc(show(c.code))}</code></td><td>${esc(c.n)}</td><td>${c.used ? who(c.used) + ' ' + tgl(c.used) : '—'}</td><td class=\"mut\">${c.used ? 'Ishlatilgan ' + esc(uzDate(c.used.at)) : 'Bekor qilingan ' + esc(uzDate(c.revoked))}</td></tr>`).join('') || '<tr><td colspan=\"4\" class=\"mut\">Yo‘q</td></tr>';\r\n    }\r\n\r\n    // Token berish (yoki ayirish). undo=true bo'lsa «Bekor qilish» taklif qilinadi.\r\n    async function give(id, n, why, undo) {\r\n      const a = AC.find((x) => x.id === id);\r\n      const r = await ADM.api('tkgive', {id, n, why: why || (n > 0 ? 'Admin qo‘shdi' : 'Admin ayirdi')});\r\n      if (!r.ok) { toast('O‘zgartirib bo‘lmadi. Qayta urinib ko‘ring.'); return; }\r\n      await load();\r\n      const name = a ? nm(a) : 'O‘qituvchi';\r\n      toast(`${name}: ${n > 0 ? '+' : ''}${n} token. Balans: ${r.bal}`, undo ? () => give(id, -n, 'Bekor qilindi', false) : null);\r\n    }\r\n\r\n    $('#kQ').oninput = rows;\r\n    $('#kR').onclick = load;\r\n    box.onclick = async (e) => {\r\n      const b = e.target.closest('button');\r\n      if (!b) return;\r\n      if (b.dataset.cp) {\r\n        try { await navigator.clipboard.writeText(b.dataset.cp); b.textContent = 'Nusxalandi ✓'; } catch (err) { prompt('Kodni nusxalang:', b.dataset.cp); }\r\n        setTimeout(() => (b.textContent = 'Nusxalash'), 1500);\r\n        return;\r\n      }\r\n      if (b.dataset.kr && confirm('Kod o‘chiriladi va endi ishlamaydi. Davom etilsinmi?')) { await ADM.api('tkrevoke', {code: b.dataset.kr}); load(); return; }\r\n      if (b.dataset.q) { b.disabled = true; await give(b.dataset.id, +b.dataset.q, '', true); return; }\r\n      if (b.dataset.cl) { openId = null; rows(); return; }\r\n      if (b.dataset.on) { openId = b.dataset.on; openMode = 'n'; rows(); const i = $('#oN'); if (i) i.focus(); return; }\r\n      if (b.dataset.oh) {\r\n        openId = b.dataset.oh; openMode = 'h'; HIST = null; rows();\r\n        const r = await ADM.api('tkacct&id=' + encodeURIComponent(openId)).catch(() => null);\r\n        if (openId !== b.dataset.oh || openMode !== 'h') return;\r\n        HIST = (r && r.ok && r.acct.log) || [];\r\n        rows();\r\n        return;\r\n      }\r\n      if (b.dataset.go) {\r\n        const n = Math.trunc(+$('#oN').value);\r\n        if (!n || Math.abs(n) > 1000) { toast('Token sonini yozing (1 dan 1000 gacha)'); return; }\r\n        const why = $('#oW').value.trim();\r\n        openId = null;\r\n        b.disabled = true;\r\n        await give(b.dataset.go, n, why, true);\r\n      }\r\n    };\r\n    $('#kB').onclick = async () => {\r\n      const n = Math.min(500, Math.max(1, Math.floor(+$('#kN').value || 0)));\r\n      const c = Math.min(50, Math.max(1, Math.floor(+$('#kC').value || 1)));\r\n      $('#kB').disabled = true;\r\n      $('#kGM').textContent = 'Yaratilmoqda...';\r\n      const r = await ADM.api('tkgen', {n, count: c});\r\n      $('#kB').disabled = false;\r\n      $('#kGM').textContent = r.ok ? `${r.codes.length} ta kod yaratildi (har biri ${n} token).` : 'Yaratib bo‘lmadi';\r\n      load();\r\n    };\r\n    load();\r\n  }\r\n\r\n  /* ================= Statistika ================= */\r\n\r\n  function Stats(box) {\r\n    box.innerHTML = `\r\n      <div class=\"hd\" style=\"margin:0 0 12px\"><div class=\"mut\" id=\"upd\">Yuklanmoqda...</div>\r\n        <div style=\"display:flex;gap:8px\"><select id=\"per\"><option value=\"7\">7 kun</option><option value=\"30\" selected>30 kun</option><option value=\"90\">90 kun</option><option value=\"0\">Hammasi</option></select><button class=\"g\" id=\"rf\">Yangilash</button></div></div>\r\n      <div class=\"kp\">\r\n        <div class=\"card\"><div class=\"l\">Jami yuklashlar</div><div class=\"n\" id=\"kT\">0</div></div>\r\n        <div class=\"card\"><div class=\"l\">PDF</div><div class=\"n\" id=\"kP\" style=\"color:var(--pdf)\">0</div></div>\r\n        <div class=\"card\"><div class=\"l\">Excel</div><div class=\"n\" id=\"kX\" style=\"color:var(--xl)\">0</div></div>\r\n        <div class=\"card\"><div class=\"l\">Bugun</div><div class=\"n\" id=\"kD\">0</div></div>\r\n        <div class=\"card\"><div class=\"l\">Foydalanuvchilar</div><div class=\"n\" id=\"kU\">0</div><div class=\"mut\" id=\"kU2\"></div></div>\r\n      </div>\r\n      <div class=\"row2\">\r\n        <div class=\"card\"><h2>Bo'limlar bo'yicha</h2><div id=\"modes\"></div><div class=\"lg\"><span style=\"--c:var(--pdf)\">PDF</span><span style=\"--c:var(--xl)\">Excel</span></div></div>\r\n        <div class=\"card\"><h2>Kunlik yuklashlar</h2><div class=\"ch\" id=\"ch\"></div><div class=\"ax\"><span id=\"a0\"></span><span id=\"a1\"></span></div>\r\n          <div class=\"lg\"><span style=\"--c:var(--bsb)\">BSB</span><span style=\"--c:var(--chsb)\">CHSB</span><span style=\"--c:var(--dg)\">Diagnostika</span></div></div>\r\n      </div>\r\n      <div class=\"card\"><h2>Foydalanuvchilar <span class=\"mut\" id=\"uc\"></span></h2>\r\n        <div class=\"tw\"><table><thead><tr><th>#</th><th>Maktab</th><th>Fanlar</th><th class=\"n\">Jami</th><th class=\"n\">PDF</th><th class=\"n\">Excel</th><th class=\"n\">BSB</th><th class=\"n\">CHSB</th><th class=\"n\">Diag.</th><th>Birinchi</th><th>Oxirgi</th></tr></thead><tbody id=\"tb\"></tbody></table></div></div>`;\r\n    const $ = (s) => box.querySelector(s);\r\n    let D = null;\r\n    const fmtN = (n) => (n || 0).toLocaleString('ru-RU');\r\n    const tday = () => new Date(Date.now() + 5 * 3600e3).toISOString().slice(0, 10);\r\n    const sh = (d, k) => { const x = new Date(d + 'T00:00:00Z'); x.setUTCDate(x.getUTCDate() + k); return x.toISOString().slice(0, 10); };\r\n    const df = (s) => (s ? new Date(s).toLocaleString('ru-RU', {timeZone: 'Asia/Tashkent', day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit'}) : '');\r\n    const top3 = (o) => Object.entries(o || {}).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([k]) => `<span class=\"tag\">${esc(k)}</span>`).join('');\r\n    async function load() {\r\n      $('#upd').textContent = 'Yuklanmoqda...';\r\n      const r = await ADM.api('stats');\r\n      if (!r.ok) { $('#upd').textContent = 'Statistikani olib bo‘lmadi'; return; }\r\n      D = r;\r\n      render();\r\n    }\r\n    function render() {\r\n      const per = +$('#per').value, T = tday(), from = per ? sh(T, -(per - 1)) : '0000';\r\n      const days = D.days.filter((d) => d.key >= from);\r\n      const sum = {}, users = new Set();\r\n      days.forEach((d) => { for (const k in d) if (typeof d[k] === 'number') sum[k] = (sum[k] || 0) + d[k]; Object.keys(d.devices || {}).forEach((u) => users.add(u)); });\r\n      const td = D.days.find((d) => d.key === T) || {};\r\n      $('#kT').textContent = fmtN(sum.total); $('#kP').textContent = fmtN(sum.pdf); $('#kX').textContent = fmtN(sum.excel); $('#kD').textContent = fmtN(td.total);\r\n      $('#kU').textContent = fmtN(users.size); $('#kU2').textContent = 'bugun: ' + Object.keys(td.devices || {}).length + ' · jami: ' + D.devices.length;\r\n      $('#upd').textContent = 'Yangilandi: ' + new Date().toLocaleTimeString('ru-RU');\r\n      const M = [['bsb', 'BSB'], ['chsb', 'CHSB'], ['dg', 'Diagnostika'], ['nj', 'Natijalar']];\r\n      const mx = Math.max(1, ...M.map(([k]) => sum[k] || 0));\r\n      $('#modes').innerHTML = M.map(([k, n]) => {\r\n        const p = (sum[k + '_pdf_jadval'] || 0) + (sum[k + '_pdf_tahlil'] || 0), x = (sum[k + '_excel_jadval'] || 0) + (sum[k + '_excel_tahlil'] || 0);\r\n        return `<div class=\"bar\"><div class=\"nm\">${n}</div><div class=\"tr\"><i style=\"width:${(p / mx) * 100}%;background:var(--pdf)\"></i><i style=\"width:${(x / mx) * 100}%;background:var(--xl)\"></i></div><div class=\"v\">${fmtN(sum[k])}</div></div>`;\r\n      }).join('');\r\n      const N = per || 60;\r\n      const by = Object.fromEntries(D.days.map((d) => [d.key, d]));\r\n      const list = [...Array(N)].map((_, i) => sh(T, i - N + 1));\r\n      const cm = Math.max(1, ...list.map((d) => (by[d] || {}).total || 0));\r\n      $('#ch').innerHTML = list.map((d) => { const o = by[d] || {}; const hh = (k) => ((o[k] || 0) / cm) * 100 + '%';\r\n        return `<div data-t=\"${d.slice(5)}: ${o.total || 0} ta\"><i style=\"height:${hh('bsb')};background:var(--bsb)\"></i><i style=\"height:${hh('chsb')};background:var(--chsb)\"></i><i style=\"height:${hh('dg')};background:var(--dg)\"></i></div>`; }).join('');\r\n      $('#a0').textContent = list[0]; $('#a1').textContent = list[list.length - 1];\r\n      const us = D.devices.filter((u) => !per || (u.last || '').slice(0, 10) >= from);\r\n      $('#uc').textContent = `(${us.length})`;\r\n      $('#tb').innerHTML = us.slice(0, 500).map((u, i) => `<tr><td>${i + 1}</td><td>${esc(u.school) || '<span class=\"mut\">—</span>'}</td><td>${top3(u.subs)}</td><td class=\"n\"><b>${fmtN(u.total)}</b></td><td class=\"n\">${fmtN(u.pdf)}</td><td class=\"n\">${fmtN(u.excel)}</td><td class=\"n\">${fmtN(u.bsb)}</td><td class=\"n\">${fmtN(u.chsb)}</td><td class=\"n\">${fmtN(u.dg)}</td><td class=\"mut\">${df(u.first)}</td><td class=\"mut\">${df(u.last)}</td></tr>`).join('') || '<tr><td colspan=\"11\" class=\"mut\">Hali yuklashlar yo‘q</td></tr>';\r\n    }\r\n    $('#rf').onclick = load;\r\n    $('#per').onchange = () => D && render();\r\n    load();\r\n  }\r\n  open(NJ ? ls.get('nj_tab', 'res') : ls.get('adm_tab', 'tk'));\r\n})();\r\n";
